VALUES ('233','Network.ftp_create','{"key": "Network.ftp_create", "title": "\u521b\u5efaFTP\u8fde\u63a5", "version": "1.0.1", "src": "astronverse.network.ftp.FTP().ftp_create", "comment": "\u5efa\u7acb\u4e0e\u5730\u5740(@{host}),\u7aef\u53e3(@{port})\u7684(@{server_type})\u8fde\u63a5\uff0c\u8f93\u51fa\u4e3a(@{ftp_instance})", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "host", "title": "\u670d\u52a1\u5668\u5730\u5740", "name": "host", "tip": "FTP/SFTP\u670d\u52a1\u5668\u5730\u5740", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "port", "title": "\u670d\u52a1\u5668\u7aef\u53e3\u53f7", "name": "port", "tip": "FTP\u5e38\u752821\uff0cSFTP\u5e38\u752822", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "name", "title": "\u7528\u6237\u540d", "name": "name", "tip": "\u6587\u4ef6\u670d\u52a1\u5668\u63d0\u4f9b\u7684\u53ef\u767b\u5f55\u8d26\u53f7", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "password", "title": "\u7528\u6237\u5bc6\u7801", "name": "password", "tip": "\u6587\u4ef6\u670d\u52a1\u5668\u63d0\u4f9b\u7684\u53ef\u767b\u5f55\u8d26\u53f7\u7684\u5bc6\u7801\uff1bSFTP\u5bc6\u94a5\u8fde\u63a5\u65f6\u4e3a\u5bc6\u94a5\u53e3\u4ee4\uff0c\u53ef\u4e3a\u7a7a", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "FtpServerType", "formType": {"type": "RADIO"}, "key": "server_type", "title": "\u670d\u52a1\u5668\u7c7b\u578b", "name": "server_type", "tip": "\u9009\u62e9FTP\u6216SFTP\u670d\u52a1\u5668", "options": [{"label": "FTP\u670d\u52a1\u5668", "value": "ftp"}, {"label": "SFTP\u670d\u52a1\u5668", "value": "sftp"}], "default": "ftp", "required": false}, {"types": "SftpLoginMode", "formType": {"type": "RADIO"}, "key": "login_mode", "title": "SFTP\u767b\u5f55\u65b9\u5f0f", "name": "login_mode", "tip": "\u5bc6\u7801\u8fde\u63a5\u6216\u5bc6\u94a5\u8fde\u63a5\uff08\u4ec5SFTP\u6709\u6548\uff09", "options": [{"label": "\u5bc6\u7801\u8fde\u63a5", "value": "password"}, {"label": "\u5bc6\u94a5\u8fde\u63a5", "value": "key"}], "default": "password", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "key_path", "title": "\u79c1\u94a5\u6587\u4ef6\u8def\u5f84", "name": "key_path", "tip": "SFTP\u5bc6\u94a5\u8fde\u63a5\u65f6\u5fc5\u586b\u7684\u79c1\u94a5\u6587\u4ef6\u8def\u5f84", "default": "", "dynamics": [{"key": "$this.key_path.show", "expression": "return $this.server_type.value == ''sftp'' && $this.login_mode.value == ''key''"}], "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "ftp_instance", "title": "\u4fdd\u5b58FTP\u8fde\u63a5\u5bf9\u8c61\u81f3", "tip": "\u5c06\u521b\u5efa\u7684FTP/SFTP\u8fde\u63a5\u5bf9\u8c61\u4fdd\u5b58\u81f3\u6307\u5b9a\u53d8\u91cf\u4e2d"}], "icon": "ftp-create-connection", "helpManual": "\u5efa\u7acb\u4e00\u4e2a\u6587\u4ef6\u670d\u52a1\u5668\u7684FTP/SFTP\u8fde\u63a5\uff0c\u5e76\u8fd4\u56de\u8fde\u63a5\u5bf9\u8c61\uff1bSFTP\u652f\u6301\u5bc6\u7801\u8fde\u63a5\u4e0e\u5bc6\u94a5\u8fde\u63a5\u4e24\u79cd\u65b9\u5f0f"}',NULL,'2026-08-16 12:43:56','2026-08-16 12:43:56');
VALUES ('241','Network.http_request','{"key": "Network.http_request", "title": "HTTP\u8bf7\u6c42", "version": "1.0.1", "src": "astronverse.network.network.Network().http_request", "comment": "\u5411URL(@{url})\u53d1\u9001HTTP\u8bf7\u6c42(@{request_type}), \u8bf7\u6c42\u5934(@{headers}), \u8bf7\u6c42\u4f53(@{body}), \u5e76\u4fdd\u5b58\u54cd\u5e94\u7ed3\u679c\u5230{@{http_response}}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "url", "title": "URL", "name": "url", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "RequestType", "formType": {"type": "SELECT"}, "key": "request_type", "title": "\u8bf7\u6c42\u7c7b\u578b", "name": "request_type", "tip": "", "options": [{"label": "post", "value": "post"}, {"label": "get", "value": "get"}, {"label": "connect", "value": "connect"}, {"label": "put", "value": "put"}, {"label": "patch", "value": "patch"}, {"label": "delete", "value": "delete"}, {"label": "options", "value": "options"}, {"label": "head", "value": "head"}, {"label": "trace", "value": "trace"}], "default": "post", "required": true}, {"types": "Str", "formType": {"type": "INPUT_PYTHON_TEXTAREAMODAL_VARIABLE"}, "key": "curl_text", "title": "curl\u62a5\u6587\u667a\u80fd\u8bc6\u522b", "name": "curl_text", "tip": "\u7c98\u8d34\u6d4f\u89c8\u5668\u300cCopy as cURL\u300d/Fiddler/Postman\u5bfc\u51fa\u7684curl\u547d\u4ee4\uff0c\u81ea\u52a8\u89e3\u6790\u586b\u5145URL/\u8bf7\u6c42\u7c7b\u578b/\u8bf7\u6c42\u5934/\u8bf7\u6c42\u4f53\uff0c\u624b\u52a8\u586b\u5199\u7684\u9879\u4f18\u5148", "default": "", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "headers", "title": "\u8bf7\u6c42\u5934", "name": "headers", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "body", "title": "\u8bf7\u6c42\u4f53", "name": "body", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.body.show", "expression": "return [''post'', ''put''].includes($this.request_type.value)"}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "file_path", "title": "\u5f85\u4e0a\u4f20\u6587\u4ef6\u8def\u5f84", "name": "file_path", "tip": "", "default": "", "dynamics": [{"key": "$this.file_path.show", "expression": "return $this.request_type.value == ''post''"}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "time_out", "title": "\u8d85\u65f6\u65f6\u95f4", "name": "time_out", "tip": "", "default": 60, "value": [{"type": "str", "value": ""}], "required": false}, {"types": "SaveType", "formType": {"type": "RADIO"}, "key": "save_type", "title": "\u54cd\u5e94\u7ed3\u679c\u4fdd\u5b58\u5230\u6587\u4ef6", "name": "save_type", "tip": "\u5c06\u54cd\u5e94\u7ed3\u679c\u4fdd\u5b58\u5230\u6307\u5b9a\u6587\u672c\u6587\u4ef6\u4e2d", "options": [{"label": "\u4fdd\u5b58", "value": "yes"}, {"label": "\u5220\u9664", "value": "no"}], "default": "no", "level": "advanced", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "save_path", "title": "\u6587\u6863\u4fdd\u5b58\u76ee\u5f55", "name": "save_path", "tip": "\u8f93\u5165\u6587\u4ef6\u4fdd\u5b58\u76ee\u5f55", "default": "", "level": "advanced", "dynamics": [{"key": "$this.save_path.show", "expression": "return $this.save_type.value == ''yes''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "save_name", "title": "\u6587\u4ef6\u540d\u79f0", "name": "save_name", "tip": "\u8f93\u5165\u4fdd\u5b58\u6587\u4ef6\u540d\u79f0\uff0c\u9ed8\u8ba4\u4e3a\u6587\u672c\u6587\u4ef6", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.save_name.show", "expression": "return $this.save_type.value == ''yes''"}], "required": true}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "http_response", "title": "\u4fdd\u5b58\u54cd\u5e94\u7ed3\u679c\u5230", "tip": ""}], "icon": "http-request", "helpManual": "\u5411\u6307\u5b9aurl\u53d1\u9001HTTP\u8bf7\u6c42"}',NULL,'2026-08-16 12:43:56','2026-08-16 12:43:56');

VALUES ('879','BrowserSoftware.http_request','{"key": "BrowserSoftware.http_request", "title": "\u901a\u8fc7\u7f51\u9875\u53d1\u9001HTTP\u8bf7\u6c42", "version": "1.0.5", "src": "astronverse.browser.browser_software.BrowserSoftware().http_request", "comment": "\u5728\u6d4f\u89c8\u5668\u5bf9\u8c61 @{browser_obj} \u4e2d\u5411URL(@{url})\u53d1\u9001(@{request_type})\u8bf7\u6c42\uff0c\u8f93\u51fa\u81f3 @{response_data}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "\u6d4f\u89c8\u5668\u5bf9\u8c61", "name": "browser_obj", "tip": "\u9009\u62e9\u5df2\u6253\u5f00\u5e76\u5b8c\u6210\u767b\u5f55\u7684\u6d4f\u89c8\u5668\u5bf9\u8c61", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "URL", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "url", "title": "URL", "name": "url", "tip": "\u8bf7\u6c42\u5730\u5740\uff0c\u5efa\u8bae\u4e0e\u7f51\u9875\u540c\u57df\u4ee5\u643a\u5e26\u767b\u5f55Cookie", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebRequestTypeFlag", "formType": {"type": "SELECT"}, "key": "request_type", "title": "\u8bf7\u6c42\u7c7b\u578b", "name": "request_type", "tip": "GET/POST/PUT/PATCH/DELETE/HEAD", "options": [{"label": "GET", "value": "get"}, {"label": "POST", "value": "post"}, {"label": "PUT", "value": "put"}, {"label": "PATCH", "value": "patch"}, {"label": "DELETE", "value": "delete"}, {"label": "HEAD", "value": "head"}], "default": "get", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "headers", "title": "\u8bf7\u6c42\u5934", "name": "headers", "tip": "JSON\u683c\u5f0f\u7684\u8bf7\u6c42\u5934\u5b57\u7b26\u4e32", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "body", "title": "\u8bf7\u6c42\u4f53", "name": "body", "tip": "POST/PUT/PATCH/DELETE\u65f6\u7684\u8bf7\u6c42\u4f53\u5185\u5bb9", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "time_out", "title": "\u8d85\u65f6\u65f6\u95f4", "name": "time_out", "tip": "\u8bf7\u6c42\u8d85\u65f6\u65f6\u95f4\uff08\u79d2\uff09", "default": 60, "value": [{"type": "str", "value": ""}], "required": false}], "outputList": [{"types": "Dict", "formType": {"type": "RESULT"}, "key": "response_data", "title": "\u54cd\u5e94\u7ed3\u679c\u4fdd\u5b58\u81f3", "tip": "\u5305\u542bstatus(\u72b6\u6001\u7801)\u3001headers(\u54cd\u5e94\u5934)\u3001body(\u54cd\u5e94\u4f53)\u7684\u5b57\u5178"}], "icon": "http-request", "helpManual": "\u501f\u52a9\u6307\u5b9a\u7f51\u9875\u7684\u767b\u5f55\u6001(Cookie)\u53d1\u9001HTTP\u8bf7\u6c42\uff0c\u9002\u7528\u4e8e\u9700\u8981\u7f51\u9875\u767b\u5f55\u8ba4\u8bc1\u7684\u63a5\u53e3\uff1b\u8bf7\u6c42\u5728\u7f51\u9875\u4e0a\u4e0b\u6587\u4e2d\u6267\u884c\uff0c\u81ea\u52a8\u643a\u5e26\u8be5\u7ad9\u70b9\u7684\u767b\u5f55Cookie"}',NULL,'2026-08-16 12:43:56','2026-08-16 12:43:56');
