INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('20','BrowserElement.click','{"key": "BrowserElement.click", "title": "点击元素（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().click", "comment": "通过 @{button_type:点击} 的形式点击浏览器对象 @{browser_obj} 中的元素 @{element_data}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要等待页面所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "拾取元素", "name": "element_data", "tip": "拾取需要操作的元素信息", "required": true, "noInput": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "simulate_flag", "title": "模拟人工点击", "name": "simulate_flag", "tip": "模拟人工点击是模拟人为操作方式点击，否则将根据拾取元素的自动化接口进行点击", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "ButtonForAssistiveKeyFlag", "formType": {"type": "SELECT"}, "key": "assistive_key", "title": "辅助按键", "name": "assistive_key", "tip": "在点击时需要按下的键盘功能按键", "options": [{"label": "无", "value": "None"}, {"label": "Alt", "value": "Alt"}, {"label": "Ctrl", "value": "Ctrl"}, {"label": "Shift", "value": "Shift"}, {"label": "Win", "value": "Win"}], "default": "None", "dynamics": [{"key": "$this.assistive_key.show", "expression": "return $this.simulate_flag.value == true"}], "required": true}, {"types": "ButtonForClickTypeFlag", "formType": {"type": "RADIO"}, "key": "button_type", "title": "点击键位", "name": "button_type", "tip": "选择模拟鼠标点击的方式", "options": [{"label": "左击", "value": "click"}, {"label": "双击", "value": "dbclick"}, {"label": "右击", "value": "right"}], "default": "click", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "scroll_into_center", "title": "元素滚动到可视区域中心", "name": "scroll_into_center", "tip": "选择是否将元素滚动到可视区域中心位置，若部分网页可能错位，可选择关闭此功能", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "dynamics": [{"key": "$this.scroll_into_center.show", "expression": "return $this.simulate_flag.value == true"}], "required": false}], "outputList": [], "icon": "click-element-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('21','BrowserElement.create_element','{"key": "BrowserElement.create_element", "title": "获取元素对象（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().create_element", "comment": "在指定的浏览器对象 @{browser_obj} 中根据 @{locate_type}获取元素对象 ，将结果输出为元素对象 @{element_obj}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "LocateType", "formType": {"type": "SELECT"}, "key": "locate_type", "title": "定位方式", "name": "locate_type", "tip": "选择 Xpath/css选择器/文字 定位方式", "options": [{"label": "xpath", "value": "xpath"}, {"label": "css选择器", "value": "cssSelector"}, {"label": "文字", "value": "text"}], "default": "xpath", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "locate_value", "title": "Xpath/css选择器/文字", "name": "locate_value", "tip": "输入对应定位方式的 Xpath / css选择器 / 文字内容", "default": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "ElementCreateReturnType", "formType": {"type": "RADIO"}, "key": "return_type", "title": "返回值类型", "name": "return_type", "tip": "选择返回单个元素对象还是元素对象列表", "options": [{"label": "单个元素对象", "value": "single"}, {"label": "元素对象列表", "value": "list"}], "default": "list", "required": true}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "element_obj", "title": "元素对象", "tip": "输出元素对象，结果为单个对象或列表"}], "icon": "get-element-object-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('22','BrowserElement.data_batch','{"key": "BrowserElement.data_batch", "title": "数据抓取（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().data_batch", "comment": "在指定的浏览器对象 @{browser_obj} 中抓取 @{batch_data} ，将结果输出为 @{table_pick}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要等待页面所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "BATCH"}}, "key": "batch_data", "title": "抓取对象", "name": "batch_data", "tip": "拾取需要抓取的元素", "required": true, "noInput": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "multi_page", "title": "是否抓取多页", "name": "multi_page", "tip": "选择需要是否抓取多页，默认抓取当前页", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "page_count", "title": "抓取页数", "name": "page_count", "tip": "填写需要抓取的总页数，例如：抓取10页，则填写10", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.page_count.show", "expression": "return $this.multi_page.value == true"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "page_interval", "title": "翻页间隔时间，单位：秒", "name": "page_interval", "tip": "填写翻页的间隔时间，若间隔时间过短导致页面加载不完全，可适当增加翻页间隔时间", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.page_interval.show", "expression": "return $this.multi_page.value == true"}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "翻页按钮", "name": "element_data", "tip": "拾取需要翻页的元素", "dynamics": [{"key": "$this.element_data.show", "expression": "return $this.multi_page.value == true"}], "required": true, "noInput": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "simulate_flag", "title": "模拟人工输入", "name": "simulate_flag", "tip": "模拟人工输入是模拟人为操作方式输入，否则将根据元素的自动化接口进行输入", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "dynamics": [{"key": "$this.simulate_flag.show", "expression": "return $this.multi_page.value == true"}], "required": false}, {"types": "ButtonForClickTypeFlag", "formType": {"type": "RADIO"}, "key": "button_type", "title": "点击键位", "name": "button_type", "tip": "选择模拟鼠标点击的方式", "options": [{"label": "左击", "value": "click"}, {"label": "双击", "value": "dbclick"}, {"label": "右击", "value": "right"}], "default": "click", "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "to_excel", "title": "存储到表格文档", "name": "to_excel", "tip": "可直接存储为excel文档", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"file_type": "file", "filters": [".xlsx"], "defaultPath": "default.xlsx"}}, "key": "excel_path", "title": "表格文档路径", "name": "excel_path", "tip": "请选择文档存储路径", "default": "", "dynamics": [{"key": "$this.excel_path.show", "expression": "return $this.to_excel.value == true"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "TablePickType", "formType": {"type": "RADIO"}, "key": "output_type", "title": "输出类型", "name": "output_type", "tip": "选择表格输出类型，默认输出为行", "options": [{"label": "按行输出", "value": "row"}, {"label": "按列输出", "value": "column"}], "default": "row", "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "output_head", "title": "是否输出表头", "name": "output_head", "tip": "选择是否输出表头，默认输出表头", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "required": false}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "output_filter_empty_col", "title": "是否过滤空列", "name": "output_filter_empty_col", "tip": "选择是否过滤表格中的空列", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "is_save_to_data_table", "title": "是否保存到数据表格", "name": "is_save_to_data_table", "tip": "选择是否将数据抓取的结果保存到数据表格中", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "scroll_into_center", "title": "元素滚动到可视区域中心", "name": "scroll_into_center", "tip": "选择是否将翻页按钮元素滚动到可视区域中心位置，若部分网页可能错位，可选择关闭此功能", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "dynamics": [{"key": "$this.scroll_into_center.show", "expression": "return $this.simulate_flag.value == true"}], "required": false}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "table_pick", "title": "表格对象", "tip": "输出获取的表格对象，数据类型：字典"}, {"types": "Str", "formType": {"type": "RESULT"}, "key": "table_path", "title": "表格路径", "tip": "输出保存的表格路径", "dynamics": [{"key": "$this.table_path.show", "expression": "return $this.to_excel.value == true"}]}], "icon": "data-scraping-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('23','BrowserElement.element_exist','{"key": "BrowserElement.element_exist", "title": "元素是否存在（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().element_exist", "comment": "浏览器对象 @{browser_obj} 中元素 @{element_data} 是否存在", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择指定的网页元素所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "元素拾取", "name": "element_data", "tip": "拾取需要等待的网页元素", "required": true, "noInput": true}], "outputList": [{"types": "Bool", "formType": {"type": "RESULT"}, "key": "element_exist", "title": "元素存在/不存在", "tip": "输出元素是否存在，存在为True，不存在为False"}], "icon": "wait-element-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('24','BrowserElement.element_operation','{"key": "BrowserElement.element_operation", "title": "元素操作（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().element_operation", "comment": "在浏览器对象 @{browser_obj} 中获取 @{element_data} 并 @{operation_type}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "拾取元素", "name": "element_data", "tip": "", "required": true, "noInput": true}, {"types": "ElementAttributeOpTypeFlag", "formType": {"type": "RADIO"}, "key": "operation_type", "title": "操作类型", "name": "operation_type", "tip": "设置-获取-删除信息", "options": [{"label": "获取属性", "value": "get"}, {"label": "设置属性", "value": "set"}, {"label": "删除属性", "value": "del"}], "default": "get", "required": true}, {"types": "ElementGetAttributeTypeFlag", "formType": {"type": "SELECT"}, "key": "get_type", "title": "信息类型", "name": "get_type", "tip": "", "options": [{"label": "获取元素文本内容", "value": "getText"}, {"label": "获取元素源代码", "value": "getHtml"}, {"label": "获取元素值", "value": "getValue"}, {"label": "获取元素链接地址", "value": "getLink"}, {"label": "获取元素属性", "value": "getAttribute"}, {"label": "获取元素位置", "value": "getPosition"}, {"label": "获取元素选中状态", "value": "getSelection"}, {"label": "获取元素样式", "value": "getStyle"}], "default": "getText", "dynamics": [{"key": "$this.get_type.show", "expression": "return $this.operation_type.value == ''get''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "attribute_name", "title": "属性名称", "name": "attribute_name", "tip": "填写属性名称，例如：id、class, data-id等", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.attribute_name.show", "expression": "return [''getAttribute'',''getStyle''].includes($this.get_type.value) || [''set'', ''del''].includes($this.operation_type.value)"}], "required": true}, {"types": "RelativePosition", "formType": {"type": "RADIO"}, "key": "position", "title": "相对位置", "name": "position", "tip": "", "options": [{"label": "屏幕左上", "value": "screenLeft"}, {"label": "页面左上", "value": "webPageLeft"}], "default": "screenLeft", "dynamics": [{"key": "$this.position.show", "expression": "return $this.get_type.value == ''getPosition''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "attribute_value", "title": "属性值", "name": "attribute_value", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.attribute_value.show", "expression": "return $this.operation_type.value == ''set''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "get_ele_attr", "title": "元素属性", "tip": "", "dynamics": [{"key": "$this.get_ele_attr.show", "expression": "return $this.get_type.value == ''getAttribute''"}]}, {"types": "Str", "formType": {"type": "RESULT"}, "key": "get_ele_value", "title": "元素值", "tip": "", "dynamics": [{"key": "$this.get_ele_value.show", "expression": "return $this.get_type.value == ''getValue''"}]}, {"types": "Str", "formType": {"type": "RESULT"}, "key": "get_ele_html", "title": "元素源代码", "tip": "", "dynamics": [{"key": "$this.get_ele_html.show", "expression": "return $this.get_type.value == ''getHtml''"}]}, {"types": "Str", "formType": {"type": "RESULT"}, "key": "get_ele_link", "title": "元素链接地址", "tip": "", "dynamics": [{"key": "$this.get_ele_link.show", "expression": "return $this.get_type.value == ''getLink''"}]}, {"types": "Str", "formType": {"type": "RESULT"}, "key": "get_ele_text", "title": "元素文本内容", "tip": "", "dynamics": [{"key": "$this.get_ele_text.show", "expression": "return $this.get_type.value == ''getText''"}]}, {"types": "List", "formType": {"type": "RESULT"}, "key": "get_ele_position", "title": "元素位置", "tip": "", "dynamics": [{"key": "$this.get_ele_position.show", "expression": "return $this.get_type.value == ''getPosition''"}]}, {"types": "Bool", "formType": {"type": "RESULT"}, "key": "get_ele_selected", "title": "元素选中状态", "tip": "", "dynamics": [{"key": "$this.get_ele_selected.show", "expression": "return $this.get_type.value == ''getSelection''"}]}, {"types": "Str", "formType": {"type": "RESULT"}, "key": "get_ele_style", "title": "元素样式", "tip": "", "dynamics": [{"key": "$this.get_ele_style.show", "expression": "return $this.get_type.value == ''getStyle''"}]}], "icon": "element-operation-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('25','BrowserElement.element_text','{"key": "BrowserElement.element_text", "title": "获取元素文本内容（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().element_text", "comment": "获取浏览器对象 @{browser_obj} 网页中拾取的元素 @{element_data} 文本内容，并将结果输出至 @{data_pick}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要获取文本的元素所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "元素拾取", "name": "element_data", "tip": "选择要获取文本的元素位置", "required": true, "noInput": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "data_pick", "title": "输出变量", "tip": "输出获取到的当前网页标题字符串"}], "icon": "get-element-text-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('26','BrowserElement.get_checked','{"key": "BrowserElement.get_checked", "title": "获取复选框（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().get_checked", "comment": "在浏览器对象 @{browser_obj} 中获取复选框 @{element_data}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "拾取复选框", "name": "element_data", "tip": "", "required": true, "noInput": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "get_checkbox_checked", "title": "复选框选中内容", "tip": ""}], "icon": "get-checkbox-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('27','BrowserElement.get_relative_element','{"key": "BrowserElement.get_relative_element", "title": "获取关联元素（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().get_relative_element", "comment": "在指定的浏览器对象 @{browser_obj} 中获取 @{element_data} 关联的 @{relative_type}，将结果输出为元素对象 @{element_obj}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "元素对象", "name": "element_data", "tip": "作为锚点的元素，只能是单个元素对象，不能是列表", "required": true, "noInput": true}, {"types": "RelativeType", "formType": {"type": "SELECT"}, "key": "relative_type", "title": "关联类型", "name": "relative_type", "tip": "选择关联类型，例如：兄弟元素、父级元素、子级元素等", "options": [{"label": "子元素", "value": "child"}, {"label": "父元素", "value": "parent"}, {"label": "兄弟元素", "value": "sibling"}], "default": "child", "required": true}, {"types": "ChildElementType", "formType": {"type": "SELECT"}, "key": "child_element_type", "title": "子元素类型", "name": "child_element_type", "tip": "选择获取子元素的类型", "options": [{"label": "所有子元素", "value": "all"}, {"label": "第n个子元素", "value": "index"}, {"label": "子元素xpath", "value": "xpath"}, {"label": "最后一个子元素", "value": "last"}], "default": "all", "dynamics": [{"key": "$this.child_element_type.show", "expression": "return $this.relative_type.value == ''child''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "child_element_xpath", "title": "子元素xpath", "name": "child_element_xpath", "tip": "填写子元素的xpath，仅获取单个元素", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.child_element_xpath.show", "expression": "return $this.child_element_type.value == ''xpath'' && $this.relative_type.value == ''child''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "child_element_index", "title": "子元素位置", "name": "child_element_index", "tip": "填写子元素位置，例如：0表示第一个子元素", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.child_element_index.show", "expression": "return $this.child_element_type.value == ''index'' && $this.relative_type.value == ''child''"}], "required": true}, {"types": "SiblingElementType", "formType": {"type": "SELECT"}, "key": "sibling_element_type", "title": "兄弟元素类型", "name": "sibling_element_type", "tip": "选择获取兄弟元素的类型", "options": [{"label": "所有兄弟元素", "value": "all"}, {"label": "下一个兄弟元素", "value": "next"}, {"label": "上一个兄弟元素", "value": "prev"}], "default": "all", "dynamics": [{"key": "$this.sibling_element_type.show", "expression": "return $this.relative_type.value == ''sibling''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "is_multiple", "title": "是否返回多个元素", "name": "is_multiple", "tip": "控制使用xpath获取子元素时返回单个/多个元素", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "dynamics": [{"key": "$this.is_multiple.show", "expression": "return $this.child_element_type.value == ''xpath'' && $this.relative_type.value == ''child''"}], "required": true}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "element_obj", "title": "元素对象", "tip": "输出元素对象，结果为单个对象或列表"}], "icon": "get-related-elements-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('28','BrowserElement.get_select','{"key": "BrowserElement.get_select", "title": "获取下拉框（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().get_select", "comment": "在浏览器对象 @{browser_obj} 中获取下拉框 @{element_data}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "拾取下拉框", "name": "element_data", "tip": "", "required": true, "noInput": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "current_content", "title": "获取当前选中内容", "name": "current_content", "tip": "选中内容或者所有内容", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "get_selected", "title": "下拉框选中内容", "tip": ""}], "icon": "get-dropdown-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('29','BrowserElement.get_table','{"key": "BrowserElement.get_table", "title": "获取表格数据（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().get_table", "comment": "获取浏览器对象 @{browser_obj} 中的表格 @{element_data} ，将结果输出为 @{table_pick}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要等待页面所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "拾取表格", "name": "element_data", "tip": "拾取网页表格中任一单元格元素，无须拾取整个表格", "required": true, "noInput": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "to_excel", "title": "存储到表格文档", "name": "to_excel", "tip": "可直接存储为excel文档", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"file_type": "file"}}, "key": "excel_path", "title": "表格文档路径", "name": "excel_path", "tip": "请选择文档存储路径", "default": "", "dynamics": [{"key": "$this.excel_path.show", "expression": "return $this.to_excel.value == true"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "table_pick", "title": "表格对象", "tip": "输出获取的表格对象，数据类型：字典"}], "icon": "get-table-data-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('30','BrowserElement.hover_over','{"key": "BrowserElement.hover_over", "title": "鼠标悬停在元素上（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().hover_over", "comment": "鼠标悬停在浏览器对象 @{browser_obj} 中的元素 @{element_data} 上", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要等待页面所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "悬停元素拾取", "name": "element_data", "tip": "拾取鼠标要悬停的元素", "required": true, "noInput": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "scroll_into_center", "title": "元素滚动到可视区域中心", "name": "scroll_into_center", "tip": "选择是否将元素滚动到可视区域中心位置，若部分网页可能错位，可选择关闭此功能", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "required": false}], "outputList": [], "icon": "mouse-hover-element-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('31','BrowserElement.input','{"key": "BrowserElement.input", "title": "填写输入框（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().input", "comment": "在指定的浏览器对象 @{browser_obj} 中拾取输入框 @{element_data} ，以 @{fill_type:键盘输入/剪贴板输入} 的形式输入内容 ，将执行结果输出至 @{form_input}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要等待页面所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "拾取输入框", "name": "element_data", "tip": "拾取需要填写内容的输入框元素", "required": true, "noInput": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "simulate_flag", "title": "模拟人工输入", "name": "simulate_flag", "tip": "模拟人工输入是模拟人为操作方式输入，否则将根据元素的自动化接口进行输入", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "FillInputForFillTypeFlag", "formType": {"type": "RADIO"}, "key": "fill_type", "title": "输入类型", "name": "fill_type", "tip": "选择填写输入框的方式", "options": [{"label": "键盘输入", "value": "text"}, {"label": "剪贴板", "value": "clipboard"}, {"label": "凭据输入", "value": "credential"}], "default": "text", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "fill_input", "title": "输入内容", "name": "fill_input", "tip": "填写输入框的内容", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.fill_input.show", "expression": "return $this.fill_type.value == ''text''"}], "required": true}, {"types": "Str", "formType": {"type": "SELECT", "params": {"filters": ["credential"]}}, "key": "fill_input_credential", "title": "选择凭据", "name": "fill_input_credential", "tip": "", "default": "", "dynamics": [{"key": "$this.fill_input_credential.show", "expression": "return $this.fill_type.value == ''credential''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "focus_time", "title": "焦点睡眠时间", "name": "focus_time", "tip": "焦点停顿时间(ms)", "default": 1000, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.focus_time.show", "expression": "return $this.simulate_flag.value == true"}], "required": false}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "write_gap_time", "title": "按键输入间隔", "name": "write_gap_time", "tip": "输入内容输入的时间间隔(s)", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.write_gap_time.show", "expression": "return $this.simulate_flag.value == true"}], "required": false}, {"types": "FillInputForInputTypeFlag", "formType": {"type": "RADIO"}, "key": "input_type", "title": "追加输入", "name": "input_type", "tip": "是否对输入框进行追加输入", "options": [{"label": "追加", "value": "append"}, {"label": "覆盖", "value": "overwrite"}], "default": "overwrite", "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "scroll_into_center", "title": "元素滚动到可视区域中心", "name": "scroll_into_center", "tip": "选择是否将元素滚动到可视区域中心位置，若部分网页可能错位，可选择关闭此功能", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "dynamics": [{"key": "$this.scroll_into_center.show", "expression": "return $this.simulate_flag.value == true"}], "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "form_input", "title": "用户输入内容", "tip": ""}], "icon": "fill-input-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('32','BrowserElement.loop_similar','{"key": "BrowserElement.loop_similar", "title": "循环相似元素列表（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().loop_similar", "comment": "获取浏览器对象 @{browser_obj} 中与拾取到的元素 @{element_data} 相似的元素，从起始项@{start}到结束项@{end}进行循环操作，输出列表循环至@{item}, 是否输出循环项位置为@{index}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择相似元素所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "相似元素拾取", "name": "element_data", "tip": "在网页上拾取不同位置的两个相似元素", "required": true, "noInput": true}, {"types": "ElementGetAttributeHasSelfTypeFlag", "formType": {"type": "SELECT"}, "key": "get_type", "title": "元素操作", "name": "get_type", "tip": "", "options": [{"label": "获取元素对象", "value": "getElement"}, {"label": "获取元素文本内容", "value": "getText"}, {"label": "获取元素源代码", "value": "getHtml"}, {"label": "获取元素值", "value": "getValue"}, {"label": "获取元素链接地址", "value": "getLink"}, {"label": "获取元素属性", "value": "getAttribute"}, {"label": "获取元素位置", "value": "getPosition"}, {"label": "获取元素选中状态", "value": "getSelection"}, {"label": "获取元素样式", "value": "getStyle"}], "default": "getElement", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "start", "title": "起始位置", "name": "start", "tip": "下标位置从0开始", "default": 0, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end", "title": "结束位置", "name": "end", "tip": "下标位置从0开始,-1代表循环至最后一个元素", "default": -1, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "attribute_name", "title": "属性名称", "name": "attribute_name", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.attribute_name.show", "expression": "return $this.get_type.value == ''getAttribute''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "Int", "formType": {"type": "RESULT"}, "key": "index", "title": "循环项位置", "tip": "默认变量可修改，用于遍历列表的变量索引数值"}, {"types": "Any", "formType": {"type": "RESULT"}, "key": "item", "title": "循环项", "tip": "默认变量可修改，用于遍历列表的变量"}], "icon": "loop-similar-elements-web", "helpManual": "", "noAdvanced": true}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
