INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('35','BrowserElement.scroll','{"key": "BrowserElement.scroll", "title": "网页滚动", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().scroll", "comment": "通过 @{scroll_direction:横向/纵向} 的方向，从（@{x_scroll_type||y_scroll_type}）滚动浏览器对象 @{browser_obj} 的滚动条", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要滑动滚动条的网页所在浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "ScrollbarType", "formType": {"type": "RADIO"}, "key": "scrollbar_type", "title": "滚动目标", "name": "scrollbar_type", "tip": "选择网页窗口滚动条或指定网页上某个滚动条元素", "options": [{"label": "窗口", "value": "window"}, {"label": "自定义目标", "value": "customEle"}], "default": "window", "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "拾取滚动条", "name": "element_data", "tip": "拾取需要在网页上滚动操作的滚动条元素", "dynamics": [{"key": "$this.element_data.show", "expression": "return $this.scrollbar_type.value == ''customEle''"}], "required": true, "noInput": true}, {"types": "ScrollDirection", "formType": {"type": "RADIO"}, "key": "scroll_direction", "title": "滚动方向", "name": "scroll_direction", "tip": "", "options": [{"label": "横向", "value": "horizontal"}, {"label": "纵向", "value": "vertical"}], "default": "horizontal", "required": true}, {"types": "ScrollbarForXScrollTypeFlag", "formType": {"type": "RADIO"}, "key": "x_scroll_type", "title": "横向滚动位置", "name": "x_scroll_type", "tip": "", "options": [{"label": "最左", "value": "left"}, {"label": "最右", "value": "right"}, {"label": "自定义", "value": "defined"}], "default": "left", "dynamics": [{"key": "$this.x_scroll_type.show", "expression": "return $this.scroll_direction.value == ''horizontal''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "x_custom_scroll_dis", "title": "横向自定义滚动距离", "name": "x_custom_scroll_dis", "tip": "单位为屏幕的分辨率像素px，一般为0-9999之间的数值", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.x_custom_scroll_dis.show", "expression": "return $this.scroll_direction.value == ''horizontal'' && $this.x_scroll_type.value == ''defined''"}], "required": true}, {"types": "ScrollbarForYScrollTypeFlag", "formType": {"type": "RADIO"}, "key": "y_scroll_type", "title": "纵向滚动位置", "name": "y_scroll_type", "tip": "", "options": [{"label": "顶部", "value": "top"}, {"label": "底部", "value": "bottom"}, {"label": "自定义", "value": "defined"}], "default": "top", "dynamics": [{"key": "$this.y_scroll_type.show", "expression": "return $this.scroll_direction.value == ''vertical''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "y_custom_scroll_dis", "title": "纵向自定义滚动距离", "name": "y_custom_scroll_dis", "tip": "单位为屏幕的分辨率像素px，一般为0-9999之间的数值", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.y_custom_scroll_dis.show", "expression": "return $this.scroll_direction.value == ''vertical'' && $this.y_scroll_type.value == ''defined''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.element_timeout.show", "expression": "return $this.scrollbar_type.value == ''customEle''"}], "required": true}], "outputList": [], "icon": "mouse-scroll-webpage", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('36','BrowserElement.scroll_into_view','{"key": "BrowserElement.scroll_into_view", "title": "元素置于可视区域（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().scroll_into_view", "comment": "将网页元素 @{element_data} 置于可视区域", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要可视的元素所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "拾取可视目标", "name": "element_data", "tip": "拾取需要可视的目标元素", "required": true, "noInput": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "scroll_into_center", "title": "元素滚动到可视区域中心", "name": "scroll_into_center", "tip": "选择是否将元素滚动到可视区域中心位置，若部分网页可能错位，可选择关闭此功能", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "required": false}], "outputList": [], "icon": "element-to-visible-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
