INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('99','DataConvertProcess.str_to_other','{"key": "DataConvertProcess.str_to_other", "title": "文本转其他格式", "version": "1.0.2", "src": "astronverse.dataprocess.dataconvert.DataConvertProcess().str_to_other", "comment": "将输入文本（字符串） @{input_data} 转换为其他格式，返回转换后的结果 @{str_convert_other}", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "input_data", "title": "输入内容", "name": "input_data", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "StringConvertType", "formType": {"type": "SELECT"}, "key": "convert_type", "title": "转换类型", "name": "convert_type", "tip": "", "options": [{"label": "字符串转列表", "value": "str_to_list"}, {"label": "字符串转字典", "value": "str_to_dict"}, {"label": "字符串转元组", "value": "str_to_tuple"}, {"label": "字符串转布尔值", "value": "str_to_bool"}, {"label": "字符串转整数", "value": "str_to_int"}, {"label": "字符串转浮点数", "value": "str_to_float"}], "default": "str_to_int", "required": true}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "str_convert_other", "title": "转换结果", "tip": ""}], "icon": "text-convert-format", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('100','DataProcess.set_variable_value','{"key": "DataProcess.set_variable_value", "title": "设置变量值", "version": "1.0.2", "src": "astronverse.dataprocess.data.DataProcess().set_variable_value", "comment": "赋值 @{value} 给变量 @{variable_var}", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "value", "title": "变量值", "name": "value", "tip": "输入需要设置的变量值", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "VariableType", "formType": {"type": "SELECT"}, "key": "variable_type", "title": "变量类型", "name": "variable_type", "tip": "选择需要设置的变量类型", "options": [{"label": "字符串", "value": "str"}, {"label": "整数", "value": "int"}, {"label": "浮点数", "value": "float"}, {"label": "布尔值", "value": "bool"}, {"label": "列表", "value": "list"}, {"label": "字典", "value": "dict"}, {"label": "JSON", "value": "json"}, {"label": "元组", "value": "tuple"}, {"label": "其他", "value": "other"}], "default": "int", "required": true}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "variable_var", "title": "设置后的变量值", "tip": "", "dynamics": [{"key": "$this.variable_var.types", "expression": "return [''int'',''str'', ''float'', ''bool'', ''list'', ''dict''].includes($this.variable_type.value) ? $this.variable_type.value[0].toUpperCase() + $this.variable_type.value.slice(1) : ''Any''"}]}], "icon": "set-variable-value", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('101','Dialog.custom_box','{"key": "Dialog.custom_box", "title": "自定义对话框", "version": "1.0.2", "src": "astronverse.dialog.dialog.Dialog().custom_box", "comment": "", "inputList": [{"types": "Str", "formType": {"type": "INPUT"}, "key": "box_title", "title": "对话框标题", "name": "box_title", "tip": "", "default": "自定义对话框", "required": true, "limitLength": [-1, 50]}, {"types": "Str", "formType": {"type": "MODALBUTTON"}, "key": "design_interface", "title": "设计对话框界面", "name": "design_interface", "tip": "点击按钮则进入对话框设计弹窗界面", "need_parse": "json_str", "required": false}, {"types": "Bool", "formType": {"type": "SWITCH"}, "key": "auto_check", "title": "无操作自动关闭对话框", "name": "auto_check", "tip": "", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "无操作超时等待（秒）", "name": "wait_time", "tip": "", "default": 60, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.wait_time.show", "expression": "return $this.auto_check.value == true"}], "required": false}, {"types": "DefaultButtonCN", "formType": {"type": "SELECT"}, "key": "default_button", "title": "超时默认选中按钮", "name": "default_button", "tip": "", "options": [{"label": "确认", "value": "confirm"}, {"label": "取消", "value": "cancel"}], "default": "confirm", "dynamics": [{"key": "$this.default_button.show", "expression": "return $this.auto_check.value == true"}], "required": true}], "outputList": [{"types": "DialogResult", "formType": {"type": "RESULT"}, "key": "dialog_result", "title": "自定义对话框结果", "tip": "存储所有表单控件的输出结果以及点击的按钮结果"}], "icon": "custom-dialog", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('102','Dialog.input_box','{"key": "Dialog.input_box", "title": "\u8f93\u5165\u5bf9\u8bdd\u6846", "version": "1.0.2", "src": "astronverse.dialog.dialog.Dialog().input_box", "comment": "", "inputList": [{"types": "Str", "formType": {"type": "INPUT"}, "key": "box_title", "title": "\u5bf9\u8bdd\u6846\u6807\u9898", "name": "box_title", "tip": "\u9650\u5236\u6807\u9898\u5185\u5bb9\u5b57\u7b26\u6570\u91cf\u4e3a50\u4e2a\u5b57\u7b26\uff0c\u4e0d\u8f93\u5165\u5219\u9ed8\u8ba4\u6807\u9898\u4e3a\u201c\u8f93\u5165\u5bf9\u8bdd\u6846\u201d", "default": "\u8f93\u5165\u5bf9\u8bdd\u6846", "required": false, "limitLength": [-1, 50]}, {"types": "InputType", "formType": {"type": "RADIO"}, "key": "input_type", "title": "\u8f93\u5165\u6846\u7c7b\u578b", "name": "input_type", "tip": "", "options": [{"label": "\u6587\u672c\u6846", "value": "text"}, {"label": "\u5bc6\u7801\u6846", "value": "password"}, {"label": "\u591a\u884c\u6587\u672c\u6846", "value": "textarea"}], "default": "text", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "input_title", "title": "\u8f93\u5165\u6846\u6807\u9898", "name": "input_title", "tip": "", "default": "\u8f93\u5165\u6846\u6807\u9898", "value": [{"type": "str", "value": ""}], "required": false, "limitLength": [-1, 60]}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "default_input_text", "title": "\u8f93\u5165\u6846\u5185\u5bb9\u9ed8\u8ba4\u503c", "name": "default_input_text", "tip": "\u586b\u5199\u5219\u5728\u5bf9\u8bdd\u6846\u4e2d\u5c55\u793a\u9ed8\u8ba4\u6587\u672c\u4f5c\u4e3a\u6587\u672c\u63d0\u793a\u7b26\uff0c\u9650\u5236\u5185\u5bb9\u5b57\u7b26\u6570\u91cf\u4e3a120\u4e2a\u5b57\u7b26", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.default_input_text.show", "expression": "return $this.input_type.value != ''password''"}], "required": false}, {"types": "Str", "formType": {"type": "DEFAULTPASSWORD"}, "key": "default_input_pwd", "title": "\u8f93\u5165\u6846\u5185\u5bb9\u9ed8\u8ba4\u503c", "name": "default_input_pwd", "tip": "\u586b\u5199\u5219\u5728\u5bf9\u8bdd\u6846\u4e2d\u5c55\u793a\u9ed8\u8ba4\u5bc6\u7801\uff0c\u5bc6\u7801\u957f\u5ea6\u57284-16\u4f4d\u4e4b\u95f4", "default": "", "dynamics": [{"key": "$this.default_input_pwd.show", "expression": "return $this.input_type.value == ''password''"}], "required": false, "limitLength": [4, 16]}, {"types": "Any", "formType": {"type": "MODALBUTTON"}, "key": "preview_button", "title": "\u9884\u89c8", "name": "preview_button", "tip": "", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "input_content", "title": "\u4fdd\u5b58\u7528\u6237\u8f93\u5165\u5185\u5bb9\u81f3", "tip": ""}, {"types": "Str", "formType": {"type": "RESULT"}, "key": "result_button", "title": "\u4fdd\u5b58\u70b9\u51fb\u7684\u6309\u94ae\u540d\u79f0\u81f3", "tip": ""}], "icon": "input-dialog", "helpManual": "\u6253\u5f00\u8f93\u5165\u5bf9\u8bdd\u6846\uff0c\u9700\u7528\u6237\u8fdb\u884c\u4fe1\u606f\u8f93\u5165\u5e76\u786e\u5b9a\u63d0\u4ea4\uff0c\u8fd4\u56de\u7528\u6237\u5728\u5bf9\u8bdd\u6846\u4e2d\u8f93\u5165\u7684\u5185\u5bb9\u3002"}',NULL,'2025-10-11 14:12:21','2026-08-16 10:34:02');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('103','Dialog.message_box','{"key": "Dialog.message_box", "title": "消息提示框", "version": "1.0.2", "src": "astronverse.dialog.dialog.Dialog().message_box", "comment": "", "inputList": [{"types": "Str", "formType": {"type": "INPUT"}, "key": "box_title", "title": "对话框标题", "name": "box_title", "tip": "用户自定义的对话框上方的显示标题，限制标题内容字符数量为50个字符。不输入则默认标题为“消息提示框”", "default": "消息提示框", "required": false, "limitLength": [-1, 50]}, {"types": "MessageType", "formType": {"type": "RADIO"}, "key": "message_type", "title": "消息类型", "name": "message_type", "tip": "可选消息类型", "options": [{"label": "信息", "value": "message"}, {"label": "警告", "value": "warning"}, {"label": "问题", "value": "question"}, {"label": "错误", "value": "error"}], "default": "message", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "message_content", "title": "消息内容", "name": "message_content", "tip": "用户自定义的对话框内的显示内容，限制内容字符数量为120个字符", "default": "", "required": true, "limitLength": [-1, 120]}, {"types": "ButtonType", "formType": {"type": "SELECT"}, "key": "button_type", "title": "展示按钮", "name": "button_type", "tip": "消息框可展示给用户进行选择的按钮，只允许切换，不允许空选状态", "options": [{"label": "确认", "value": "confirm"}, {"label": "确认-取消", "value": "confirm_cancel"}, {"label": "是-否", "value": "yes_no"}, {"label": "是-否-取消", "value": "yes_no_cancel"}], "default": "confirm", "required": true}, {"types": "Bool", "formType": {"type": "SWITCH"}, "key": "auto_check", "title": "无操作自动关闭对话框", "name": "auto_check", "tip": "", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "无操作超时等待（秒）", "name": "wait_time", "tip": "设置超时等待时间，未识别到用户鼠标移动行为超过该时间则选中默认按钮，默认为60秒", "default": 60, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.wait_time.show", "expression": "return $this.auto_check.value == true"}], "required": false}, {"types": "DefaultButtonC", "formType": {"type": "SELECT"}, "key": "default_button_c", "title": "超时默认选中按钮", "name": "default_button_c", "tip": "", "options": [{"label": "确认", "value": "confirm"}], "default": "confirm", "dynamics": [{"key": "$this.default_button_c.show", "expression": "return $this.auto_check.value == true && $this.button_type.value == ''confirm''"}], "required": true}, {"types": "DefaultButtonCN", "formType": {"type": "SELECT"}, "key": "default_button_cn", "title": "超时默认选中按钮", "name": "default_button_cn", "tip": "", "options": [{"label": "确认", "value": "confirm"}, {"label": "取消", "value": "cancel"}], "default": "confirm", "dynamics": [{"key": "$this.default_button_cn.show", "expression": "return $this.auto_check.value == true && $this.button_type.value == ''confirm_cancel''"}], "required": true}, {"types": "DefaultButtonY", "formType": {"type": "SELECT"}, "key": "default_button_y", "title": "超时默认选中按钮", "name": "default_button_y", "tip": "", "options": [{"label": "是", "value": "yes"}, {"label": "否", "value": "no"}], "default": "yes", "dynamics": [{"key": "$this.default_button_y.show", "expression": "return $this.auto_check.value == true && $this.button_type.value == ''yes_no''"}], "required": true}, {"types": "DefaultButtonYN", "formType": {"type": "SELECT"}, "key": "default_button_yn", "title": "超时默认选中按钮", "name": "default_button_yn", "tip": "", "options": [{"label": "是", "value": "yes"}, {"label": "否", "value": "no"}, {"label": "取消", "value": "cancel"}], "default": "yes", "dynamics": [{"key": "$this.default_button_yn.show", "expression": "return $this.auto_check.value == true && $this.button_type.value == ''yes_no_cancel''"}], "required": true}, {"types": "Any", "formType": {"type": "MODALBUTTON"}, "key": "preview_button", "title": "预览", "name": "preview_button", "tip": "", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "result_button", "title": "保存用户选择的按钮至", "tip": ""}], "icon": "message-dialog", "helpManual": "打开消息提示对话框，可设定消息提示的内容和标题。"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('104','Dialog.select_box','{"key": "Dialog.select_box", "title": "\u9009\u62e9\u5bf9\u8bdd\u6846", "version": "1.0.2", "src": "astronverse.dialog.dialog.Dialog().select_box", "comment": "", "inputList": [{"types": "Str", "formType": {"type": "INPUT"}, "key": "box_title", "title": "\u5bf9\u8bdd\u6846\u6807\u9898", "name": "box_title", "tip": "", "default": "\u9009\u62e9\u5bf9\u8bdd\u6846", "required": false, "limitLength": [-1, 50]}, {"types": "SelectType", "formType": {"type": "RADIO"}, "key": "select_type", "title": "\u9009\u62e9\u6a21\u5f0f", "name": "select_type", "tip": "", "options": [{"label": "\u5355\u9009", "value": "single"}, {"label": "\u591a\u9009", "value": "multi"}], "default": "single", "required": true}, {"types": "SelectKind", "formType": {"type": "RADIO"}, "key": "select_kind", "title": "\u9009\u62e9\u6846\u7c7b\u578b", "name": "select_kind", "tip": "\u4e0b\u62c9\u6846\u4e3a\u6298\u53e0\u4e0b\u62c9\u9009\u62e9\uff0c\u5217\u8868\u4e3a\u5e73\u94fa\u5c55\u793a\u9009\u9879", "options": [{"label": "\u4e0b\u62c9\u6846", "value": "dropdown"}, {"label": "\u5217\u8868", "value": "list"}], "default": "dropdown", "required": false}, {"types": "List", "formType": {"type": "OPTIONSLIST"}, "key": "options", "title": "\u9009\u9879", "name": "options", "tip": "", "default": [], "need_parse": "str", "required": true}, {"types": "Str", "formType": {"type": "INPUT"}, "key": "options_title", "title": "\u9009\u62e9\u6846\u6807\u9898", "name": "options_title", "tip": "", "default": "", "required": false}, {"types": "Any", "formType": {"type": "MODALBUTTON"}, "key": "preview_button", "title": "\u9884\u89c8", "name": "preview_button", "tip": "", "required": false}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "select_result", "title": "\u4fdd\u5b58\u9009\u62e9\u7ed3\u679c\u81f3", "tip": ""}], "icon": "select-dialog", "helpManual": "\u6253\u5f00\u9009\u62e9\u5bf9\u8bdd\u6846\uff0c\u4fdd\u5b58\u7528\u6237\u4ece\u9009\u62e9\u5217\u8868\u4e2d\u9009\u62e9\u7684\u4e00\u4e2a\u6216\u591a\u4e2a\u9009\u9879"}',NULL,'2025-10-11 14:12:21','2026-08-16 10:34:02');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('105','Dialog.select_file_box','{"key": "Dialog.select_file_box", "title": "文件选择对话框", "version": "1.0.2", "src": "astronverse.dialog.dialog.Dialog().select_file_box", "comment": "", "inputList": [{"types": "Str", "formType": {"type": "INPUT"}, "key": "box_title_file", "title": "对话框标题", "name": "box_title_file", "tip": "", "default": "文件选择框", "dynamics": [{"key": "$this.box_title_file.show", "expression": "return $this.open_type.value == ''file''"}], "required": false, "limitLength": [-1, 50]}, {"types": "Str", "formType": {"type": "INPUT"}, "key": "box_title_folder", "title": "对话框标题", "name": "box_title_folder", "tip": "", "default": "文件夹选择框", "dynamics": [{"key": "$this.box_title_folder.show", "expression": "return $this.open_type.value == ''folder''"}], "required": false, "limitLength": [-1, 50]}, {"types": "OpenType", "formType": {"type": "RADIO"}, "key": "open_type", "title": "打开类型", "name": "open_type", "tip": "", "options": [{"label": "文件", "value": "file"}, {"label": "文件夹", "value": "folder"}], "default": "file", "required": false}, {"types": "FileType", "formType": {"type": "SELECT"}, "key": "file_type", "title": "文件类型", "name": "file_type", "tip": "", "options": [{"label": "所有文件", "value": "*"}, {"label": "Excel", "value": ".xls,.xlsx"}, {"label": "Word", "value": ".doc,.docx"}, {"label": "文本文件", "value": ".txt"}, {"label": "图像文件", "value": ".png,.jpg,.jpeg,.bmp,.gif"}, {"label": "PPT文件", "value": ".ppt,.pptx"}, {"label": "压缩文件", "value": ".zip,.rar"}], "default": "*", "dynamics": [{"key": "$this.file_type.show", "expression": "return $this.open_type.value == ''file''"}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH"}, "key": "multiple_choice", "title": "是否允许多选", "name": "multiple_choice", "tip": "", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "dynamics": [{"key": "$this.multiple_choice.show", "expression": "return $this.open_type.value == ''file''"}], "required": false}, {"types": "Str", "formType": {"type": "INPUT"}, "key": "select_title", "title": "选择框标题", "name": "select_title", "tip": "", "default": "", "required": false, "limitLength": [-1, 60]}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "default_path", "title": "默认文件夹", "name": "default_path", "tip": "当配置了该参数，则在打开文件选择框时默认解析在该文件夹路径进行下一步选择", "default": "", "required": false}, {"types": "Any", "formType": {"type": "MODALBUTTON"}, "key": "preview_button", "title": "预览", "name": "preview_button", "tip": "", "required": false}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "select_file", "title": "保存文件选择结果至", "tip": "保存用户的文件选择结果，如果用户点击取消按钮则返回为空值"}], "icon": "file-select-dialog", "helpManual": "打开系统选择文件对话框，保存用户选择的对应的文件/文件夹路径"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
