INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('117','Docx.convert_format','{"key": "Docx.convert_format", "title": "Word导出为PDF/TXT", "version": "1.0.2", "src": "astronverse.word.docx.Docx().convert_format", "comment": "在Word对象 @{doc} 中，导出指定内容为PDF或TXT文件", "inputList": [{"types": "DocumentObject", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "doc", "title": "Word对象", "name": "doc", "tip": "本软件前序原子能力（如打开、创建）返回的Word对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "output_path", "title": "导出路径", "name": "output_path", "tip": "选择要导出的文件夹", "default": "", "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "default_name", "title": "是否使用默认名称", "name": "default_name", "tip": "选择是否使用默认名称", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "output_name", "title": "导出文件名", "name": "output_name", "tip": "输入不含格式后缀的文件名", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.output_name.show", "expression": "return $this.default_name.value == false"}], "required": true}, {"types": "FileType", "formType": {"type": "RADIO"}, "key": "output_file_type", "title": "导出文件格式", "name": "output_file_type", "tip": "选中导出为pdf还是txt", "options": [{"label": "PDF", "value": "pdf"}, {"label": "TXT", "value": "txt"}], "default": "pdf", "required": true}, {"types": "ConvertPageType", "formType": {"type": "SELECT"}, "key": "page_type", "title": "页面范围", "name": "page_type", "tip": "选择要导出全部页面、指定页面范围、当前页面、当前选中内容", "options": [{"label": "全部页面", "value": 0}, {"label": "当前页面", "value": 2}, {"label": "指定页面范围", "value": 3}, {"label": "选中内容", "value": 1}], "default": 0, "dynamics": [{"key": "$this.page_type.show", "expression": "return $this.output_file_type.value == ''pdf''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "page_start", "title": "起始页面", "name": "page_start", "tip": "输入导出的起始页面", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.page_start.show", "expression": "return $this.page_type.value == ''3'' && $this.output_file_type.value == ''pdf''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "page_end", "title": "结束页面", "name": "page_end", "tip": "输入要导出的结束页面", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.page_end.show", "expression": "return $this.page_type.value == ''3'' && $this.output_file_type.value == ''pdf''"}], "required": true}, {"types": "SaveFileType", "formType": {"type": "RADIO"}, "key": "save_type", "title": "重名保存方式", "name": "save_type", "tip": "选择存在重名文件时报错、覆盖、自动重命名", "options": [{"label": "重名提示", "value": "warn"}, {"label": "自动生成名称", "value": "generate"}, {"label": "覆盖同名文件", "value": "overwrite"}], "default": "warn", "required": true}], "outputList": [], "icon": "word-export-pdf-txt", "helpManual": ""}',NULL,'2025-10-14 08:41:00','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('118','Docx.create_comment','{"key": "Docx.create_comment", "title": "Word创建批注", "version": "1.0.2", "src": "astronverse.word.docx.Docx().create_comment", "comment": "在Word对象 @{doc} 中，创建批注", "inputList": [{"types": "DocumentObject", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "doc", "title": "Word对象", "name": "doc", "tip": "本软件前序原子能力（如打开、创建）返回的Word对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "comment", "title": "批注内容", "name": "comment", "tip": "输入批注内容", "default": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "CommentType", "formType": {"type": "RADIO"}, "key": "comment_type", "title": "批注对象", "name": "comment_type", "tip": "选择指定范围还是指定内容", "options": [{"label": "指定位置", "value": "position"}, {"label": "指定内容", "value": "content"}], "default": "position", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "paragraph_idx", "title": "段落号", "name": "paragraph_idx", "tip": "输入创建批注的段落号", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.paragraph_idx.show", "expression": "return $this.comment_type.value == ''position''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "start", "title": "起始字符序号", "name": "start", "tip": "输入批注的起始字符序号", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.start.show", "expression": "return $this.comment_type.value == ''position''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end", "title": "结束字符序号", "name": "end", "tip": "输入批注的结束字符序号", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.end.show", "expression": "return $this.comment_type.value == ''position''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "target_str", "title": "目标内容", "name": "target_str", "tip": "输入批注的目标内容", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.target_str.show", "expression": "return $this.comment_type.value == ''content''"}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "comment_all", "title": "全部批注", "name": "comment_all", "tip": "选择是否全部批注", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "dynamics": [{"key": "$this.comment_all.show", "expression": "return $this.comment_type.value == ''content''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "comment_index", "title": "序号", "name": "comment_index", "tip": "选择批注内容的序号", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.comment_index.show", "expression": "return $this.comment_all.value == false"}], "required": true}], "outputList": [], "icon": "word-create-comment", "helpManual": ""}',NULL,'2025-10-14 08:41:00','2026-02-24 17:09:16');
