INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('122','Docx.get_cursor_position','{"key": "Docx.get_cursor_position", "title": "\u5b9a\u4f4dWord\u5149\u6807", "version": "1.0.2", "src": "astronverse.word.docx.Docx().get_cursor_position", "comment": "\u5728Word\u5bf9\u8c61 @{doc} \u4e2d\u5b9a\u4f4d\u5149\u6807\u4f4d\u7f6e", "inputList": [{"types": "DocumentObject", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "doc", "title": "Word\u5bf9\u8c61", "name": "doc", "tip": "\u672c\u8f6f\u4ef6\u524d\u5e8f\u539f\u5b50\u80fd\u529b\uff08\u5982\u6253\u5f00\u3001\u521b\u5efa\uff09\u8fd4\u56de\u7684Word\u5bf9\u8c61", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "CursorPointerType", "formType": {"type": "SELECT"}, "key": "by", "title": "\u5149\u6807\u5b9a\u4f4d\u65b9\u5f0f", "name": "by", "tip": "\u9009\u62e9\u5b9a\u4f4d\u5230\u5168\u6587\u3001\u6bb5\u843d\u3001\u884c\u3001\u6587\u672c\u3001\u4e66\u7b7e", "options": [{"label": "\u6587\u6863", "value": "all"}, {"label": "\u6bb5\u843d", "value": "paragraph"}, {"label": "\u884c", "value": "row"}, {"label": "\u6587\u672c\u5185\u5bb9", "value": "content"}, {"label": "\u4e66\u7b7e", "value": "bookmark"}], "default": "all", "required": true}, {"types": "CursorPositionType", "formType": {"type": "RADIO"}, "key": "pos", "title": "\u5149\u6807\u76f8\u5bf9\u4f4d\u7f6e", "name": "pos", "tip": "\u6240\u9009\u5185\u5bb9\u4e4b\u524d/\u6240\u9009\u5185\u5bb9\u4e4b\u540e", "options": [{"label": "\u6240\u9009\u5185\u5bb9\u4e4b\u524d", "value": "head"}, {"label": "\u6240\u9009\u5185\u5bb9\u4e4b\u540e", "value": "tail"}], "default": "head", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "content", "title": "\u6587\u672c\u5185\u5bb9", "name": "content", "tip": "\u5982\u679c\u9009\u62e9\u5b9a\u4f4d\u6587\u672c\uff0c\u8f93\u5165\u6587\u672c\u5185\u5bb9", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.content.show", "expression": "return $this.by.value == ''content''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "c_idx", "title": "\u6587\u672c\u5e8f\u53f7", "name": "c_idx", "tip": "\u8f93\u5165\u5b9a\u4f4d\u6587\u672c\u7684\u5e8f\u53f7", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.c_idx.show", "expression": "return $this.by.value == ''content''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "p_idx", "title": "\u6bb5\u843d\u53f7", "name": "p_idx", "tip": "\u8f93\u5165\u5b9a\u4f4d\u6bb5\u843d\u53f7", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.p_idx.show", "expression": "return $this.by.value == ''paragraph''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "r_idx", "title": "\u884c\u53f7", "name": "r_idx", "tip": "\u9009\u62e9\u5b9a\u4f4d\u7684\u884c\u53f7", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.r_idx.show", "expression": "return $this.by.value == ''row''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "bookmark", "title": "\u4e66\u7b7e\u540d\u79f0", "name": "bookmark", "tip": "\u5982\u679c\u9009\u62e9\u5b9a\u4f4d\u4e66\u7b7e\uff0c\u8f93\u5165\u4e66\u7b7e\u540d\u79f0", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.bookmark.show", "expression": "return $this.by.value == ''bookmark''"}], "required": true}], "outputList": [], "icon": "word-position-cursor", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-08-16 13:26:04');
