INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('125','Docx.insert_img','{"key": "Docx.insert_img", "title": "Word插入图片", "version": "1.0.2", "src": "astronverse.word.docx.Docx().insert_img", "comment": "在Word对象 @{doc} 中，从路径 @{img_path} 或剪贴板插入图片", "inputList": [{"types": "DocumentObject", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "doc", "title": "Word对象", "name": "doc", "tip": "本软件前序原子能力（如打开、创建）返回的Word对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "InsertImgType", "formType": {"type": "RADIO"}, "key": "img_from", "title": "图片来源", "name": "img_from", "tip": "选择通过文件路径、剪贴板", "options": [{"label": "文件", "value": "file"}, {"label": "剪贴板", "value": "clipboard"}], "default": "file", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "img_path", "title": "文件路径", "name": "img_path", "tip": "输入文件路径", "default": "", "dynamics": [{"key": "$this.img_path.show", "expression": "return $this.img_from.value == ''file''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "scale", "title": "缩放比例（%）", "name": "scale", "tip": "默认为100%，可以输入其他值，不需要输入百分号", "default": 100, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "newline", "title": "是否换行", "name": "newline", "tip": "选择插入前是否换行", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}], "outputList": [], "icon": "word-insert-image", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
