INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('127','Docx.insert_table','{"key": "Docx.insert_table", "title": "Word插入表格", "version": "1.0.2", "src": "astronverse.word.docx.Docx().insert_table", "comment": "在Word对象 @{doc} 中，插入表格内容", "inputList": [{"types": "DocumentObject", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "doc", "title": "Word对象", "name": "doc", "tip": "本软件前序原子能力（如打开、创建）返回的Word对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "List", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "table_content", "title": "表格内容", "name": "table_content", "tip": "要创建的表格内容,格式为二维数组或者为读取的Excel表格内容", "default": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "TableBehavior", "formType": {"type": "RADIO"}, "key": "table_behavior", "title": "表格大小", "name": "table_behavior", "tip": "选择默认还是适应大小", "options": [{"label": "默认", "value": 0}, {"label": "适应大小", "value": 1}], "default": 0, "required": true}, {"types": "RowAlignment", "formType": {"type": "RADIO"}, "key": "alignment", "title": "文本左右位置", "name": "alignment", "tip": "选择左对齐、居中对齐、右对齐", "options": [{"label": "左对齐", "value": 0}, {"label": "居中对齐", "value": 1}, {"label": "右对齐", "value": 2}], "default": 0, "required": true}, {"types": "VerticalAlignment", "formType": {"type": "RADIO"}, "key": "v_alignment", "title": "文本垂直位置", "name": "v_alignment", "tip": "选择顶部对齐、居中对齐、底部对齐", "options": [{"label": "顶部对齐", "value": 0}, {"label": "居中对齐", "value": 1}, {"label": "底部对齐", "value": 3}], "default": 0, "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "border", "title": "表格边框", "name": "border", "tip": "选择是否有边框", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "if_change_font", "title": "是否改变字体", "name": "if_change_font", "tip": "选择是否改变字体", "