INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('133','Docx.save_docx','{"key": "Docx.save_docx", "title": "保存Word", "version": "1.0.2", "src": "astronverse.word.docx.Docx().save_docx", "comment": "保存Word对象 @{doc} ，保存方式为 @{save_type}, 并输出保存路径 @{save_file_path}", "inputList": [{"types": "DocumentObject", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "doc", "title": "Word对象", "name": "doc", "tip": "本软件前序原子能力（如打开、创建）返回的Word对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "SaveType", "formType": {"type": "RADIO"}, "key": "save_type", "title": "保存类型", "name": "save_type", "tip": "选择保存类型，如保存、另存为、不保存", "options": [{"label": "保存", "value": "save"}, {"label": "另存为", "value": "save_as"}, {"label": "不保存", "value": "abort"}], "default": "save", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "file_path", "title": "文档路径", "name": "file_path", "tip": "填写Word的保存路径", "default": "", "dynamics": [{"key": "$this.file_path.show", "expression": "return $this.save_type.value == ''save_as''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "file_name", "title": "文档名称", "name": "file_name", "tip": "填写Word的名称", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.file_name.show", "expression": "return $this.save_type.value == ''save_as''"}], "required": true}, {"types": "FileExistenceType", "formType": {"type": "RADIO"}, "key": "exist_handle_type", "title": "存在同名文件处理方式", "name": "exist_handle_type", "tip": "选择存在文件处理方式，支持覆盖原有文件、创建文件副本、跳过保存操作", "options": [{"label": "覆盖原有文件", "value": "overwrite"}, {"label": "创建文件副本", "value": "rename"}, {"label": "跳过保存操作", "value": "cancel"}], "default": "rename", "dynamics": [{"key": "$this.exist_handle_type.show", "expression": "return $this.save_type.value == ''save_as''"}], "required": true}, {