INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('135','Email.receive_email','{"key": "Email.receive_email", "title": "接收邮件", "version": "1.0.2", "src": "astronverse.email.email.Email().receive_email", "comment": "从邮箱(@{user_mail})接收邮件信息", "inputList": [{"types": "EmailServerType", "formType": {"type": "SELECT"}, "key": "mail_server", "title": "邮件服务器地址", "name": "mail_server", "tip": "选择一个邮箱类型", "options": [{"label": "其他邮箱", "value": "other"}, {"label": "126", "value": "126"}, {"label": "163", "value": "163"}, {"label": "QQ", "value": "qq"}, {"label": "讯飞邮箱", "value": "iflytek"}], "default": "qq", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "custom_mail_server", "title": "IMAP服务器地址", "name": "custom_mail_server", "tip": "输入指定的IMAP服务器地址", "default": "", "value": [{"type": "str", "value": ""}], "level": "normal", "dynamics": [{"key": "$this.custom_mail_server.show", "expression": "return $this.mail_server.value == ''other''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "custom_mail_port", "title": "IMAP服务器端口", "name": "custom_mail_port", "tip": "输入指定的IMAP服务器端口", "default": 993, "value": [{"type": "str", "value": ""}], "level": "normal", "dynamics": [{"key": "$this.custom_mail_port.show", "expression": "return $this.mail_server.value == ''other''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "user_mail", "title": "用户邮件账号", "name": "user_mail", "tip": "IMAP服务器身份验证的用户名，通常是邮箱账号，以具体邮件服务商的规范为标准", "default": "", "value": [{"type": "str", "value": ""}], "level": "normal", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "user_password", "title": "授权码", "name": "user_password", "tip": "IMAP服务器验证身份的授权码，一般需要短信认证开通，部分邮箱为账号密码，以具体邮件服务商的规范为标准", "default": "", "value": [{"type": "str", "value": ""}], "level": "normal", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "max_return_num", "title": "邮件最大返回数量", "name": "max_return_num", "tip": "返回的最大邮件数量", "default": 5, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "CHECKBOX"}, "key": "unseen_flag", "title": "仅未读邮件", "name": "unseen_flag", "tip": "仅获取未读邮件或全部邮件", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "level": "normal", "required": true}, {"types": "Bool", "formType": {"type": "CHECKBOX"}, "key": "save_attachment_flag", "title": "保存附件", "name": "save_attachment_flag", "tip": "是否下载邮件附件", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "level": "normal", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "files"}}, "key": "save_attachment_path", "title": "保存目录", "name": "save_attachment_path", "tip": "附件的保存目录", "default": "", "level": "normal", "dynamics": [{"key": "$this.save_attachment_path.show", "expression": "return $this.save_attachment_flag.value == true"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "folder_name", "title": "文件夹名称", "name": "folder_name", "tip": "输入要接收邮件的邮件箱名称，默认为INBOX", "default": "INBOX", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "CHECKBOX"}, "key": "mask_as_read_flag", "title": "标记为已读", "name": "mask_as_read_flag", "tip": "获取邮件后，将邮件标记为已读状态", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "sender_text", "title": "发件人中包含的内容", "name": "sender_text", "tip": "通过发送者包含关键字进行过滤", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "receiver_text", "title"