ics": [{"key": "$this.col.show", "expression": "return $this.select_type.value == ''column''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "data_range", "title": "单元格范围", "name": "data_range", "tip": "输入连续的单元格范围，如A1:B2", "default": "A1:B5", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.data_range.show", "expression": "return $this.select_type.value == ''area''"}], "required": true}, {"types": "ClearType", "formType": {"type": "RADIO"}, "key": "clear_type", "title": "清除类型", "name": "clear_type", "tip": "", "options": [{"label": "清除内容", "value": "content"}, {"label": "清除格式", "value": "style"}, {"label": "清除内容和格式", "value": "all"}], "default": "content", "required": true}], "outputList": [], "icon": "excel-clear-range", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
