"value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.start_col.show", "expression": "return [''column'', ''area''].includes($this.select_type.value)"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end_col", "title": "结束列", "name": "end_col", "tip": "输入结束列编号，-n代表倒数第n列", "default": "-1", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.end_col.show", "expression": "return [''column'', ''area''].includes($this.select_type.value)"}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "real_text", "title": "是否获取可见值", "name": "real_text", "tip": "Excel的可见值为打开所见到的值，真实值可能是隐藏的公式等，选择否获取真实值", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "cell_strip", "title": "是否去除空格", "name": "cell_strip", "tip": "是否去除前后空格以及换行符", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "key", "title": "循环项位置", "tip": "例如 A, B"}, {"types": "Any", "formType": {"type": "RESULT"}, "key": "value", "title": "循环项", "tip": "例如 [1.0, None]"}], "icon": "excel-loop-content", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
