INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('203','Gui.keyboard','{"key": "Gui.keyboard", "title": "\u952e\u76d8\u8f93\u5165", "version": "1.0.1", "src": "astronverse.input.gui_key.GuiKeyBoard().keyboard", "comment": "\u901a\u8fc7(@{keyboard_type})\u65b9\u5f0f\u6a21\u62df\u952e\u76d8\u8f93\u5165(@{message})", "inputList": [{"types": "KeyboardType", "formType": {"type": "SELECT"}, "key": "keyboard_type", "title": "\u8f93\u5165\u65b9\u5f0f", "name": "keyboard_type", "tip": "\u666e\u901a\u8f93\u5165\uff1awindows\u952e\u76d8\u6d88\u606f\u7684\u65b9\u5f0f\u6765\u6a21\u62df\u6309\u952e\u8f93\u5165\uff1b\u526a\u5207\u677f\u8f93\u5165\uff1a\u83b7\u53d6\u526a\u5207\u677f\u5185\u5bb9\u5e76\u7c98\u8d34\u8f93\u5165\uff1b\u6309\u952e\u7ec4\u5408\uff1a\u4f7f\u7528\u63d2\u5165\u952e\u76d8\u7b26\u53f7\u7ec4\u5408\u5feb\u6377\u8f93\u5165\uff1b\u9a71\u52a8\u8f93\u5165\uff1a\u4f7f\u7528\u9a71\u52a8\u6765\u6a21\u62df\u6309\u952e\u8f93\u5165\uff0c\u4e00\u822c\u7528\u4e8e\u7f51\u94f6\u5bc6\u7801\u6846\u8f93\u5165\u573a\u666f\u6216\u5176\u5b83\u666e\u901a\u8f93\u5165\u65b9\u5f0f\u65e0\u6cd5\u8f93\u5165\u7684\u573a\u666f", "options": [{"label": "\u666e\u901a\u8f93\u5165", "value": "normal"}, {"label": "\u7279\u6b8a\u6309\u952e\u8f93\u5165", "value": "special"}, {"label": "\u9a71\u52a8\u8f93\u5165", "value": "driver"}, {"label": "\u526a\u8d34\u677f\u8f93\u5165", "value": "clip"}, {"label": "ghost\u8f93\u5165", "value": "gblid"}], "default": "normal", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON", "params": {"size": "middle"}}, "key": "message", "title": "\u8f93\u5165\u5185\u5bb9", "name": "message", "tip": "", "default": "", "dynamics": [{"key": "$this.message.show", "expression": "return [''normal'', ''special'', ''driver'', ''gblid''].includes($this.keyboard_type.value)"}], "required": true}, {"types": "Simulate_flag", "formType": {"type": "RADIO"}, "key": "simulate_flag", "title": "\u6a21\u62df\u4eba\u5de5\u8f93\u5165", "name": "simulate_flag", "tip": "\u6a21\u62df\u4eba\u5de5\u65b9\u5f0f\u64cd\u4f5c\u952e\u76d8\u9010\u4e2a\u8f93\u5165\u5b57\u7b26\uff0c\u9ed8\u8ba4\u4e3a\u5426", "options": [{"label": "\u662f", "value": "yes"}, {"label": "\u5426", "value": "no"}], "default": "no", "dynamics": [{"key": "$this.simulate_flag.show", "expression": "return $this.keyboard_type.value == ''normal''"}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "interval", "title": "\u8f93\u5165\u95f4\u9694", "name": "interval", "tip": "\u8bbe\u7f6e\u8f93\u5165\u95f4\u9694\uff0c\u5355\u4f4d\u4e3a\u79d2", "default": 0.1, "value": [{"type": "str", "value": ""}], "level": "advanced", "dynamics": [{"key": "$this.interval.show", "expression": "return [''normal'', ''special'', ''driver''].includes($this.keyboard_type.value)"}], "required": true}], "outputList": [], "icon": "keyboard-input", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-08-16 16:30:00');
