INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('205','Gui.mouse','{"key": "Gui.mouse", "title": "\u9f20\u6807\u70b9\u51fb", "version": "1.0.1", "src": "astronverse.input.gui_mouse.GuiMouse().mouse", "comment": "\u6a21\u62df\u9f20\u6807(@{btn_type:\u5de6\u952e/\u53f3\u952e/\u4e2d\u952e}) (@{btn_model:\u6309\u4e0b/\u5f39\u8d77/\u5355\u673a/\u53cc\u51fb}))", "inputList": [{"types": "BtnType", "formType": {"type": "RADIO"}, "key": "btn_type", "title": "\u9f20\u6807\u6309\u952e", "name": "btn_type", "tip": "\u9009\u62e9\u70b9\u51fb\u9f20\u6807\u4e0a\u7684\u952e\u4f4d", "options": [{"label": "\u5de6\u952e", "value": "left"}, {"label": "\u4e2d\u952e", "value": "middle"}, {"label": "\u53f3\u952e", "value": "right"}], "default": "left", "required": true}, {"types": "BtnModel", "formType": {"type": "SELECT"}, "key": "btn_model", "title": "\u70b9\u51fb\u65b9\u5f0f", "name": "btn_model", "tip": "\u9009\u62e9\u64cd\u4f5c\u9f20\u6807\u7684\u70b9\u51fb\u65b9\u5f0f", "options": [{"label": "\u5355\u51fb", "value": "click"}, {"label": "\u53cc\u51fb", "value": "double_click"}, {"label": "\u6309\u4e0b", "value": "down"}, {"label": "\u5f39\u8d77", "value": "up"}], "default": "click", "required": true}, {"types": "ControlType", "formType": {"type": "SELECT"}, "key": "ctrl_type", "title": "\u952e\u76d8\u8f85\u52a9\u6309\u952e", "name": "ctrl_type", "tip": "\u9009\u62e9\u952e\u76d8\u8f85\u52a9\u6309\u952e\uff0c\u9ed8\u8ba4\u4e3a\u65e0", "options": [{"label": "\u65e0", "value": "none"}, {"label": "ctrl", "value": "ctrl"}, {"label": "alt", "value": "alt"}, {"label": "shift", "value": "shift"}, {"label": "win", "value": "win"}, {"label": "space", "value": "space"}], "default": "none", "level": "advanced", "required": true}, {"types": "ClickMoveType", "formType": {"type": "RADIO"}, "key": "click_move_type", "title": "\u70b9\u51fb\u524d\u79fb\u52a8\u9f20\u6807", "name": "click_move_type", "tip": "\u70b9\u51fb\u524d\u5c06\u9f20\u6807\u79fb\u52a8\u5230\u6307\u5b9a\u4f4d\u7f6e\uff0c\u9ed8\u8ba4\u5728\u5f53\u524d\u4f4d\u7f6e\u70b9\u51fb", "options": [{"label": "\u5f53\u524d\u4f4d\u7f6e\u70b9\u51fb", "value": "current"}, {"label": "\u79fb\u52a8\u5230\u5c4f\u5e55\u6307\u5b9a\u4f4d\u7f6e", "value": "screen"}, {"label": "\u79fb\u52a8\u5230\u6fc0\u6d3b\u7a97\u53e3\u5185\u6307\u5b9a\u4f4d\u7f6e", "value": "active_window"}], "default": "current", "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "click_x", "title": "\u70b9\u51fb\u4f4d\u7f6e\u6a2a\u5750\u6807x", "name": "click_x", "tip": "\u79fb\u52a8\u5230\u5c4f\u5e55/\u6fc0\u6d3b\u7a97\u53e3\u5185\u6307\u5b9a\u4f4d\u7f6e\u65f6\u586b\u5199", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.click_x.show", "expression": "return [''screen'', ''active_window''].includes($this.click_move_type.value)"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "click_y", "title": "\u70b9\u51fb\u4f4d\u7f6e\u7eb5\u5750\u6807y", "name": "click_y", "tip": "\u79fb\u52a8\u5230\u5c4f\u5e55/\u6fc0\u6d3b\u7a97\u53e3\u5185\u6307\u5b9a\u4f4d\u7f6e\u65f6\u586b\u5199", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.click_y.show", "expression": "return [''screen'', ''active_window''].includes($this.click_move_type.value)"}], "required": true}, {"types": "Speed", "formType": {"type": "RADIO"}, "key": "click_move_speed", "title": "\u79fb\u52a8\u901f\u5ea6", "name": "click_move_speed", "tip": "", "options": [{"label": "\u6162\u901f", "value": "slow"}, {"label": "\u6b63\u5e38", "value": "normal"}, {"label": "\u5feb\u901f", "value": "fast"}], "default": "normal", "level": "advanced", "dynamics": [{"key": "$this.click_move_speed.show", "expression": "return [''screen'', ''active_window''].includes($this.click_move_type.value)"}], "required": true}], "outputList": [], "icon": "mouse-click", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-