INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('206','Gui.mouse_drag','{"key": "Gui.mouse_drag", "title": "鼠标拖拽", "version": "1.0.1", "src": "astronverse.input.gui_mouse.GuiMouse().mouse_drag", "comment": "模拟鼠标从起点位置(@{start_pos_x}, @{start_pos_y})拖拽到终点位置(@{end_pos_x}, @{end_pos_y})", "inputList": [{"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON", "params": {"size": "middle"}}, "key": "start_pos_x", "title": "鼠标起点x位置", "name": "start_pos_x", "tip": "", "default": 0, "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON", "params": {"size": "middle"}}, "key": "start_pos_y", "title": "鼠标起点y位置", "name": "start_pos_y", "tip": "", "default": 0, "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON", "params": {"size": "middle"}}, "key": "end_pos_x", "title": "鼠标终点x位置", "name": "end_pos_x", "tip": "", "default": 0, "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON", "params": {"size": "middle"}}, "key": "end_pos_y", "title": "鼠标终点y位置", "name": "end_pos_y", "tip": "", "default": 0, "required": true}, {"types": "BtnType", "formType": {"type": "RADIO"}, "key": "btn_type", "title": "鼠标按键", "name": "btn_type", "tip": "拖拽时按下的鼠标键位", "options": [{"label": "左键", "value": "left"}, {"label": "中键", "value": "middle"}, {"label": "右键", "value": "right"}], "default": "left", "required": true}, {"types": "MoveType", "formType": {"type": "RADIO"}, "key": "move_type", "title": "移动方式", "name": "move_type", "tip": "选择鼠标移动方式", "options": [{"label": "匀速直线移动", "value": "linear"}, {"label": "模拟人工方式", "value": "simulation"}, {"label": "瞬时移动", "value": "teleportation"}], "default": "linear", "required": true}, {"types": "Speed", "formType": {"type": "RADIO"}, "key": "move_speed", "title": "移动速度", "name": "move_speed", "tip": "选择鼠标移动速度", "options": [{"label": "慢速", "value": "slow"}, {"label": "正常", "value": "normal"}, {"label": "快速", "value": "fast"}], "default": "normal", "dynamics": [{"key": "$this.move_speed.show", "expression": "return [''linear'', ''simulation''].includes($this.move_type.value)"}], "required": true}, {"types": "ControlType", "formType": {"type": "SELECT"}, "key": "ctrl_type", "title": "键盘辅助按键", "name": "ctrl_type", "tip": "选择鼠标拖拽时的键盘辅助按键，默认为无", "options": [{"label": "无", "value": "none"}, {"label": "ctrl", "value": "ctrl"}, {"label": "alt", "value": "alt"}, {"label": "shift", "value": "shift"}, {"label": "win", "value": "win"}, {"label": "space", "value": "space"}], "default": "none", "required": true}], "outputList": [], "icon": "mouse-drag", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('207','Gui.mouse_move','{"key": "Gui.mouse_move", "title": "\u9f20\u6807\u79fb\u52a8", "version": "1.0.1", "src": "astronverse.input.gui_mouse.GuiMouse().mouse_move", "comment": "\u5728(@{window_type})\u4e0a\u6a21\u62df\u9f20\u6807\u79fb\u52a8\u5230(@{position_x}, @{position_y})", "inputList": [{"types": "WindowType", "formType": {"type": "RADIO"}, "key": "window_type", "title": "\u7a97\u53e3\u7c7b\u578b", "name": "window_type", "tip": "\u6574\u4e2a\u5c4f\u5e55\uff1a\u4ee5\u5c4f\u5e55\u5de6\u4e0a\u89d2\u4e3a\u5750\u6807\u76f8\u5bf9\u4f4d\u7f6e\uff1b\u6fc0\u6d3b\u7a97\u53e3\uff1a\u4ee5\u6fc0\u6d3b\u7a97\u53e3\u5de6\u4e0a\u89d2\u4e3a\u76f8\u5bf9\u5750\u6807\u4f4d\u7f6e", "options": [{"label": "\u6574\u4e2a\u5c4f\u5e55", "value": "fullscreen"}, {"label": "\u6fc0\u6d3b\u7a97\u53e3", "value": "active_window"}, {"label": "\u5f53\u524d\u9f20\u6807\u4f4d\u7f6e", "value": "current_position"}], "default": "fullscreen", "required": true}, {"types": "List", "formType": {"type": "INPUT_VARIABLE_PYTHON", "params": {"size": "middle"}}, "key": "window_position", "title": "\u7a97\u53e3\u5de6\u4e0a\u89d2\u4f4d\u7f6e", "name": "window_position", "tip": "", "default": [], "dynamics": [{"key": "$this.window_position.show", "expression": "return $this.window_type.value == ''active_window''"}], "required": true}, {"types": "Str", "formType": {"type": "MOUSEPOSITION", "params": {"size": "middle"}}, "key": "get_mouse_position", "title": "\u83b7\u53d6\u9f20\u6807\u4f4d\u7f6e", "name": "get_mouse_position", "tip": "", "default": "", "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON", "params": {"size": "middle"}}, "key": "position_x", "title": "\u9f20\u6807x\u4f4d\u7f6e", "name": "position_x", "tip": "", "default": 0, "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON", "params": {"size": "middle"}}, "key": "position_y", "title": "\u9f20\u6807y\u4f4d\u7f6e", "name": "position_y", "tip": "", "default": 0, "required": true}, {"types": "MoveType", "formType": {"type": "RADIO"}, "key": "move_type", "title": "\u9f20\u6807\u79fb\u52a8\u65b9\u5f0f", "name": "move_type", "tip": "\u9009\u62e9\u9f20\u6807\u79fb\u52a8\u65b9\u5f0f", "options": [{"label": "\u5300\u901f\u76f4\u7ebf\u79fb\u52a8", "value": "linear"}, {"label": "\u6a21\u62df\u4eba\u5de5\u65b9\u5f0f", "value": "simulation"}, {"label": "\u77ac\u65f6\u79fb\u52a8", "value": "teleportation"}], "default": "linear", "required": true}, {"types": "Speed", "formType": {"type": "RADIO"}, "key": "move_speed", "title": "\u9f20\u6807\u79fb\u52a8\u901f\u5ea6", "name": "move_speed", "tip": "", "options": [{"label": "\u6162\u901f", "value": "slow"}, {"label": "\u6b63\u5e38", "value": "normal"}, {"label": "\u5feb\u901f", "value": "fast"}], "default": "normal", "level": "advanced", "dynamics": [{"key": "$this.move_speed.show", "expression": "return [''linear'', ''simulation''].includes($this.move_type.value)"}], "required": true}], "outputList": [], "icon": "mouse-move", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-08-16 16:30:00');
