INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('209','Gui.mouse_wheel','{"key": "Gui.mouse_wheel", "title": "鼠标滚动", "version": "1.0.1", "src": "astronverse.input.gui_mouse.GuiMouse().mouse_wheel", "comment": "模拟鼠标(@{scroll_type})滚动(@{scroll_px||times}),滚动方向为:(@{direction})", "inputList": [{"types": "ScrollType", "formType": {"type": "RADIO"}, "key": "scroll_type", "title": "滚动方式", "name": "scroll_type", "tip": "", "options": [{"label": "按次数", "value": "time"}, {"label": "按像素", "value": "px"}], "default": "time", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "times", "title": "自定义次数", "name": "times", "tip": "输入鼠标滚动的次数,默认滚动一次距离为120个网页像素", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.times.show", "expression": "return $this.scroll_type.value == ''time''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "scroll_px", "title": "自定义像素", "name": "scroll_px", "tip": "输入自定义像素，单位为px，一般为0-9999之间的数值", "default": 120, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.scroll_px.show", "expression": "return $this.scroll_type.value == ''px''"}], "required": true}, {"types": "Direction", "formType": {"type": "RADIO"}, "key": "direction", "title": "滚动方向", "name": "direction", "tip": "", "options": [{"label": "向上", "value": "up"}, {"label": "向下", "value": "down"}], "default": "down", "required": true}, {"types": "ControlType", "formType": {"type": "SELECT"}, "key": "ctrl_type", "title": "键盘辅助按键", "name": "ctrl_type", "tip": "选择键盘辅助按键，默认为无", "options": [{"label": "无", "value": "none"}, {"label": "ctrl", "value": "ctrl"}, {"label": "alt", "value": "alt"}, {"label": "shift", "value": "shift"}, {"label": "win", "value": "win"}, {"label": "space", "value": "space"}], "default": "none", "dynamics": [{"key": "$this.ctrl_type.show", "expression": "return [''px'', ''time''].includes($this.scroll_type.value)"}], "required": true}], "outputList": [], "icon": "mouse-scroll-webpage", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
