ADIO"}, "key": "margin_type", "title": "边距（单位毫米）", "name": "margin_type", "tip": "", "options": [{"label": "自定义", "value": "custom"}, {"label": "默认", "value": "default"}], "default": "default", "dynamics": [{"key": "$this.margin_type.show", "expression": "return $this.printer_type.value == ''custom''"}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "left_margin", "title": "左边距", "name": "left_margin", "tip": "", "default": 10, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.left_margin.show", "expression": "return $this.margin_type.value == ''custom'' && $this.printer_type.value == ''custom''"}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "top_margin", "title": "上边距", "name": "top_margin", "tip": "", "default": 9.5, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.top_margin.show", "expression": "return $this.margin_type.value == ''custom'' && $this.printer_type.value == ''custom''"}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "right_margin", "title": "右边距", "name": "right_margin", "tip": "", "default": 10, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.right_margin.show", "expression": "return $this.margin_type.value == ''custom'' && $this.printer_type.value == ''custom''"}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "bottom_margin", "title": "下边距", "name": "bottom_margin", "tip": "", "default": 9.5, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.bottom_margin.show", "expression": "return $this.margin_type.value == ''custom'' && $this.printer_type.value == ''custom''"}], "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "printer_status", "title": "打印结果", "tip": "保存打印结果到输出变量，数据类型为布尔值"}], "icon": "printer-print", "helpManual": "连接指定打印机进行文档打印"}',NULL,