INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('279','System.run_command','{"key": "System.run_command", "title": "运行或打开", "version": "1.0.1", "src": "astronverse.system.process.Process().run_command", "comment": "运行或打开 @{command} ，并将执行结果保存到输出变量 @{process_out}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "command", "title": "命令或可执行文件", "name": "command", "tip": "输入cmd命令行或可执行.exe文件", "default": "", "required": true}, {"types": "CmdType", "formType": {"type": "RADIO"}, "key": "cmd_type", "title": "运行方式", "name": "cmd_type", "tip": "选择命令行执行方式", "options": [{"label": "运行", "value": "normal"}, {"label": "管理员身份运行", "value": "admin"}], "default": "normal", "required": false}, {"types": "RunType", "formType": {"type": "RADIO"}, "key": "run_type", "title": "在指令执行结束之后", "name": "run_type", "tip": "选择是否继续执行指令，或等待程序执行结束", "options": [{"label": "继续执行下一指令", "value": "continue"}, {"label": "等待指令执行结束", "value": "complete"}], "default": "continue", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "params", "title": "参数", "name": "params", "tip": "程序执行的所需参数", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "work_dir", "title": "工作目录", "name": "work_dir", "tip": "所执行命令的工作目录", "default": "", "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待时间不超过", "name": "wait_time", "tip": "指定命令执行的等待时间，默认60秒", "default": 60, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.wait_time.show", "expression": "return $this.run_type.value == ''complete''"}], "required": false}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "process_out", "title": "保存执行结果至", "tip": "输出