INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('281','System.screen_shot','{"key": "System.screen_shot", "title": "屏幕截图", "version": "1.0.1", "src": "astronverse.system.system.System().screen_shot", "comment": "按 @{screen_type} 方式截图并保存到 @{png_path} ，输出图片保存路径 @{screenshot_path}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "png_path", "title": "图片保存路径", "name": "png_path", "tip": "输入或选择截图后的文件保存路径", "default": "", "required": true}, {"types": "StateType", "formType": {"type": "RADIO"}, "key": "state_type", "title": "路径不存在时", "name": "state_type", "tip": "选择图片保存文件夹不存在时执行的操作", "options": [{"label": "创建", "value": "create"}, {"label": "提示并报错", "value": "error"}], "default": "error", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "png_name", "title": "图片保存名称", "name": "png_name", "tip": "输入截图后的文件名，不需加文件后缀", "default": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "ScreenType", "formType": {"type": "RADIO"}, "key": "screen_type", "title": "截图区域", "name": "screen_type", "tip": "指定截图区域", "options": [{"label": "全屏", "value": "full"}, {"label": "选择区域", "value": "region"}], "default": "full", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "top_left_x", "title": "左上角x坐标", "name": "top_left_x", "tip": "输入截图的矩形区域左上角横坐标，单位为像素px", "default": 0, "dynamics": [{"key": "$this.top_left_x.show", "expression": "return $this.screen_type.value == ''region''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "top_left_y", "title": "左上角y坐标", "name": "top_left_y", "tip": "输入截图的矩形区域左上角纵坐标，单位为像素px", "default": 0, "dynamics": [{"key": "$this.top_left_y.show", "expression": "return $this.screen_type.value == ''region''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARI