INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('680','DataTable.copy_data','{"key": "DataTable.copy_data", "title": "复制数据表格", "version": "1.0.3", "src": "astronverse.datatable.datatable.DataTable().copy_data", "comment": "复制数据表格中的 @{copy_type} 数据到剪切板", "inputList": [{"types": "BaseOperateType", "formType": {"type": "SELECT"}, "key": "copy_type", "title": "复制方式", "name": "copy_type", "tip": "选择复制数据的方式（单元格、行、列、区域）", "options": [{"label": "单元格", "value": "cell"}, {"label": "行", "value": "row"}, {"label": "列", "value": "column"}, {"label": "区域", "value": "area"}], "default": "cell", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "row", "title": "行号", "name": "row", "tip": "指定要复制的行号（例如1，2，3...）", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.row.show", "expression": "return [''row'', ''cell''].includes($this.copy_type.value)"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "col", "title": "列号", "name": "col", "tip": "指定要复制的列号（例如A，B，C，AB...）", "default": "A", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.col.show", "expression": "return [''column'', ''cell''].includes($this.copy_type.value)"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "start_row", "title": "开始行号", "name": "start_row", "tip": "指定要复制的开始行号（例如1，2，3...）", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.start_row.show", "expression": "return $this.copy_type.value == ''area''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "start_col", "title": "开始列号", "name": "start_col", "tip": "指定要复制的开始列号（例如A，B，C，AB...）", "default": "A", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.start_col.show", "expression": "return $this.copy_type.value == ''area''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end_row", "title": "结束行号", "name": "end_row", "tip": "结束行号需要大于等于开始行号，0或者不填则读取已编辑区域", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.end_row.show", "expression": "return $this.copy_type.value == ''area''"}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end_col", "title": "结束列号", "name": "end_col", "tip": "结束列号需要大于等于开始列号，不填则读取已编辑区域", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.end_col.show", "expression": "return $this.copy_type.value == ''area''"}], "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "copied_cell", "title": "复制的单元格", "tip": "以字符串形式返回复制的单元格数据", "dynamics": [{"key": "$this.copied_cell.show", "expression": "return $this.copy_type.value == ''cell''"}]}, {"types": "List", "formType": {"type": "RESULT"}, "key": "copied_row", "title": "复制的行", "tip": "以数组形式返回复制的行数据", "dynamics": [{"key": "$this.copied_row.show", "expression": "return $this.copy_type.value == ''row''"}]}, {"types": "List", "formType": {"type": "RESULT"}, "key": "copied_column", "title": "复制的列", "tip": "以数组形式返回复制的列数据", "dynamics": [{"key": "$this.copied_column.show", "expression": "return $this.copy_type.value == ''column''"}]}, {"types": "List", "formType": {"type": "RESULT"}, "key": "copied_area", "title": "复制的区域", "tip": "以二维数组形式返回复制的区域数据", "dynamics": [{"key": "$this.copied_area.show", "expression": "return $this.copy_type.value == ''area''"}]}], "icon": "copy_data_table", "helpManual": ""}',NULL,'2026-01-27 17:17:49','2026-02-24 17:09:16');
