INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('683','DataTable.filter_data_table','{"key": "DataTable.filter_data_table", "title": "数据表格筛选", "version": "1.0.3", "src": "astronverse.datatable.datatable.DataTable().filter_data_table", "comment": "根据 @{filter_type} 条件筛选数据表格", "inputList": [{"types": "FilterType", "formType": {"type": "SELECT"}, "key": "filter_type", "title": "筛选类型", "name": "filter_type", "tip": "选择筛选类型（列筛选、行筛选、表格筛选）", "options": [{"label": "行筛选", "value": "row"}, {"label": "列筛选", "value": "column"}, {"label": "表格筛选", "value": "table"}], "default": "column", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "row", "title": "行号", "name": "row", "tip": "指定要筛选的行号", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.row.show", "expression": "return $this.filter_type.value == ''row''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "col", "title": "列号", "name": "col", "tip": "指定要筛选的列号", "default": "A", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.col.show", "expression": "return $this.filter_type.value == ''column''"}], "required": true}, {"types": "ConditionType", "formType": {"type": "SELECT"}, "key": "condition_type", "title": "条件类型", "name": "condition_type", "tip": "选择条件类型", "options": [{"label": "等于", "value": "equals"}, {"label": "不等于", "value": "not_equals"}, {"label": "大于", "value": "greater_than"}, {"label": "小于", "value": "less_than"}, {"label": "大于等于", "value": "greater_than_or_equal"}, {"label": "小于等于", "value": "less_than_or_equal"}, {"label": "包含", "value": "contains"}, {"label": "不包含", "value": "not_contains"}, {"label": "为空", "value": "is_empty"}, {"label": "不为空", "value": "is_not_empty"}, {"label": "开头是", "value": "starts_with"}, {"label": "结尾是", "value": "ends_with"}, {"label": "在此日期之前", "value": "date_before"}, {"label": "在此日期之后", "value": "date_after"}, {"label": "在此日期之间", "value": "date_between"}], "default": "equals", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "condition_value", "title": "条件值", "name": "condition_value", "tip": "输入条件值", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.condition_value.show", "expression": "return ![''date_after'', ''date_before'', ''date_between''].includes($this.condition_type.value)"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "date_value", "title": "日期值", "name": "date_value", "tip": "选择日期值", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.date_value.show", "expression": "return [''date_after'', ''date_before''].includes($this.condition_type.value)"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "date_range", "title": "日期范围", "name": "date_range", "tip": "选择日期范围", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.date_range.show", "expression": "return $this.condition_type.value == ''date_between''"}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "is_case_sensitive", "title": "区分大小写", "name": "is_case_sensitive", "tip": "筛选时是否区分大小写", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "dynamics": [{"key": "$this.is_case_sensitive.show", "expression": "return [''equals'', ''not_equals'', ''contains'', ''not_contains'', ''starts_with'', ''ends_with''].includes($this.condition_type.value)"}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "is_save_filtered", "title": "保存筛选结果", "name": "is_save_filtered", "tip": "是否保存筛选结果", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "data_filtered", "title": "筛选结果", "tip": "返回筛选后的数据结果"}], "icon": "filter_data_table", "helpManual": ""}',NULL,'2026-01-27 17:17:49','2026-02-24 17:09:16');
