INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('698','ComputerUse.run','{"key": "ComputerUse.run", "title": "计算机使用代理", "version": "1.0.1", "src": "astronverse.cua.computer_use.ComputerUse().run", "comment": "使用视觉大模型分析屏幕并执行GUI自动化任务：@{instruction}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "instruction", "title": "用户指令", "name": "instruction", "tip": "描述要执行的GUI自动化任务，例如\\"打开计算器并计算123+456\\"", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "max_steps", "title": "最大执行步数", "name": "max_steps", "tip": "任务执行的最大步数限制，防止无限循环", "default": 20, "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "temperature", "title": "模型温度", "name": "temperature", "tip": "模型生成时的温度参数，控制输出的随机性，默认0", "default": 0.0, "value": [{"type": "str", "value": ""}], "required": false}], "outputList": [{"types": "Dict", "formType": {"type": "RESULT"}, "key": "computer_use_res", "title": "执行结果", "tip": "包含任务执行状态、步数、耗时、截图目录和错误信息的字典"}], "icon": "computer-use", "helpManual": "使用说明：\\n1. 支持的操作包括：点击、双击、右键、拖拽、快捷键、输入文本、滚动等\\n2. Agent会自动循环执行直到任务完成或达到最大步数\\n3. 所有截图会保存在指定目录，可用于调试和验证\\n"}',NULL,'2026-01-27 17:17:49','2026-02-24 17:09:16');
