itle": "存在同名文件处理方式", "name": "exist_handle_type", "tip": "", "options": [{"label": "覆盖原有文件", "value": "overwrite"}, {"label": "创建文件副本", "value": "rename"}, {"label": "跳过保存操作", "value": "cancel"}], "default": "rename", "required": true}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "pdf_file_path", "title": "PDF文件路径", "tip": ""}], "icon": "pdf-page-to-image", "helpManual": ""}',NULL,'2026-02-02 14:31:26','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('706','Gui.mouse_move_new','{"key": "Gui.mouse_move_new", "title": "\u9f20\u6807\u79fb\u52a8", "version": "1.0.1", "src": "astronverse.input.gui_mouse.GuiMouse().mouse_move_new", "comment": "\u5728(@{window_type})\u4e0a\u6a21\u62df\u9f20\u6807\u79fb\u52a8\u5230(@{position_x}, @{position_y})", "inputList": [{"types": "WindowType", "formType": {"type": "RADIO"}, "key": "window_type", "title": "\u7a97\u53e3\u7c7b\u578b", "name": "window_type", "tip": "\u6574\u4e2a\u5c4f\u5e55\uff1a\u4ee5\u5c4f\u5e55\u5de6\u4e0a\u89d2\u4e3a\u5750\u6807\u76f8\u5bf9\u4f4d\u7f6e\uff1b\u6fc0\u6d3b\u7a97\u53e3\uff1a\u4ee5\u6fc0\u6d3b\u7a97\u53e3\u5de6\u4e0a\u89d2\u4e3a\u76f8\u5bf9\u5750\u6807\u4f4d\u7f6e", "options": [{"label": "\u6574\u4e2a\u5c4f\u5e55", "value": "fullscreen"}, {"label": "\u6fc0\u6d3b\u7a97\u53e3", "value": "active_window"}, {"label": "\u5f53\u524d\u9f20\u6807\u4f4d\u7f6e", "value": "current_position"}], "default": "fullscreen", "required": true}, {"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "WINDOW"}}, "key": "window_pick", "title": "\u7a97\u53e3\u62fe\u53d6", "name": "window_pick", "tip": "\u9009\u62e9\u9700\u8981\u64cd\u4f5c\u7684\u7a97\u53e3", "dynamics": [{"key": "$this.window_pick.show", "expression": "return $this.window_type.value == ''active_window''"}], "required": true, "noInput": true}, {"types": "Str", "formType": {"type": "MOUSEPOSITION", "params": {"size": "middle"}}, "key": "get_mouse_position", "title": "\u83b7\u53d6\u9f20\u6807\u4f4d\u7f6e", "name": "get_mouse_position", "tip": "", "default": "", "dynamics": [{"key": "$this.get_mouse_position.show", "expression": "return $this.window_type.value == ''fullscreen''"}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON", "params": {"size": "middle"}}, "key": "position_x", "title": "\u9f20\u6807x\u4f4d\u7f6e", "name": "position_x", "tip": "", "default": 0, "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON", "params": {"size": "middle"}}, "key": "position_y", "title": "\u9f20\u6807y\u4f4d\u7f6e", "name": "position_y", "tip": "", "default": 0, "required": true}, {"types": "MoveType", "formType": {"type": "RADIO"}, "key": "move_type", "title": "\u9f20\u6807\u79fb\u52a8\u65b9\u5f0f", "name": "move_type", "tip": "\u9009\u62e9\u9f20\u6807\u79fb\u52a8\u65b9\u5f0f", "options": [{"label": "\u5300\u901f\u76f4\u7ebf\u79fb\u52a8", "value": "linear"}, {"label": "\u6a21\u62df\u4eba\u5de5\u65b9\u5f0f", "value": "simulation"}, {"label": "\u77ac\u65f6\u79fb\u52a8", "value": "teleportation"}], "default": "linear", "required": true}, {"types": "Speed", "formType": {"type": "RADIO"}, "key": "move_speed", "title": "\u9f20\u6807\u79fb\u52a8\u901f\u5ea6", "name": "move_speed", "tip": "", "options": [{"label": "\u6162\u901f", "value": "slow"}, {"label": "\u6b63\u5e38", "value": "normal"}, {"label": "\u5feb\u901f", "value": "fast"}], "default": "normal", "level": "advanced", "dynamics": [{"key": "$this.move_speed.show", "expression": "return [''linear'', ''simulation''].includes($this.move_type.value)"}], "required": true}], "outputList": [], "icon": "mouse-move", "helpManual": ""}',NULL,'2026-02-02 14:31:26','2026-08-16 16:30:00');
