INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('708','IeBrowserElement.click','{"key": "IeBrowserElement.click", "title": "点击元素（ie）", "version": "1.0.5", "src": "astronverse.iebrowser.browser_element.IeBrowserElement().click", "comment": "通过 @{button_type:点击} 的形式点击浏览器对象 @{browser_obj} 中的元素 @{element_data}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要等待页面所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "拾取元素", "name": "element_data", "tip": "拾取需要操作的元素信息", "required": true, "noInput": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "simulate_flag", "title": "模拟人工点击", "name": "simulate_flag", "tip": "模拟人工点击是模拟人为操作方式点击，否则将根据拾取元素的自动化接口进行点击", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "ButtonForAssistiveKeyFlag", "formType": {"type": "SELECT"}, "key": "assistive_key", "title": "辅助按键", "name": "assistive_key", "tip": "在点击时需要按下的键盘功能按键", "options": [{"label": "无", "value": "None"}, {"label": "Alt", "value": "Alt"}, {"label": "Ctrl", "value": "Ctrl"}, {"label": "Shift", "value": "Shift"}, {"label": "Win", "value": "Win"}], "default": "None", "dynamics": [{"key": "$this.assistive_key.show", "expression": "return $this.simulate_flag.value == true"}], "required": true}, {"types": "ButtonForClickTypeFlag", "formType": {"type": "RADIO"}, "key": "button_type", "title": "点击键位", "name": "button_type", "tip": "选择模拟鼠标点击的方式", "options": [{"label": "左击", "value": "click"}, {"label": "双击", "value": "dbclick"}, {"label": "右击", "value": "right"}], "default": "click", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "scroll_into_center", "title": "元素滚动到可视区域中心", "name": "scroll_into_center", "tip": "选择是否将元素滚动到可视区域中心位置，若部分网页可能错位，可选择关闭此功能", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "level": "advanced", "dynamics": [{"key": "$this.scroll_into_center.show", "expression": "return $this.simulate_flag.value == true"}], "required": false}], "outputList": [], "icon": "click-element-web", "helpManual": ""}',NULL,'2026-02-06 17:44:39','2026-02-24 17:09:16');
