INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('769','ListProcess.filter_empty_items','{"key": "ListProcess.filter_empty_items", "title": "过滤空值项", "version": "1.0.2", "src": "astronverse.dataprocess.list.ListProcessExtend().filter_empty_items", "comment": "删除列表 @{list_data} 中的空值项（一维列表删除空值项，二维列表删除全空行），返回过滤后的列表 @{filtered_list_data}", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "list_data", "title": "列表数据", "name": "list_data", "tip": "一维列表移除 None、空串、纯空白串；二维列表移除整行均为空值的行", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "only_trim_trailing", "title": "仅去除末尾空值", "name": "only_trim_trailing", "tip": "勾选后仅移除末尾连续的空值项（或空行），适合处理表格尾部空行", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "filtered_list_data", "title": "过滤后的列表", "tip": ""}], "icon": "list-remove-multiple", "helpManual": ""}',NULL,'2026-08-15 12:00:00','2026-08-15 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('770','ListProcess.slice_list','{"key": "ListProcess.slice_list", "title": "截取列表项", "version": "1.0.2", "src": "astronverse.dataprocess.list.ListProcessExtend().slice_list", "comment": "在列表 @{list_data} 中截取从 @{start_index} 到 @{end_index} 的项（含起始、不含结束），结果为 @{sliced_list_data}", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "list_data", "title": "原列表", "name": "list_data", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "start_index", "title": "起始位置", "name": "start_index", "tip": "包含该位置的项，支持负数（-1 表示倒数第一项）", "default": 0, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end_index", "title": "结束位置", "name": "end_index", "tip": "不包含该位置的项，支持负数（-1 表示倒数第一项）", "default": -1, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "sliced_list_data", "title": "截取后的列表", "tip": ""}], "icon": "get-list-value-by-index", "helpManual": ""}',NULL,'2026-08-15 12:00:00','2026-08-15 12:00:00');
