INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('859','Dialog.message_notification','{"key": "Dialog.message_notification", "title": "\u6d88\u606f\u901a\u77e5", "version": "1.0.2", "src": "astronverse.dialog.dialog.Dialog().message_notification", "comment": "", "inputList": [{"types": "NotifyOperate", "formType": {"type": "RADIO"}, "key": "operate", "title": "\u64cd\u4f5c", "name": "operate", "tip": "\u6253\u5f00\u6d88\u606f\u901a\u77e5/\u5173\u95ed\u6d88\u606f\u901a\u77e5", "options": [{"label": "\u6253\u5f00\u6d88\u606f\u901a\u77e5", "value": "open"}, {"label": "\u5173\u95ed\u6d88\u606f\u901a\u77e5", "value": "close"}], "default": "open", "required": true}, {"types": "Str", "formType": {"type": "INPUT"}, "key": "notify_id", "title": "\u901a\u77e5\u6807\u8bc6", "name": "notify_id", "tip": "\u5173\u95ed\u64cd\u4f5c\u65f6\u6307\u5b9a\u8981\u5173\u95ed\u7684\u901a\u77e5\u6807\u8bc6", "default": "", "dynamics": [{"key": "$this.notify_id.show", "expression": "return $this.operate.value == ''close''"}], "required": false, "limitLength": [-1, 50]}, {"types": "NotifyType", "formType": {"type": "RADIO"}, "key": "message_type", "title": "\u6d88\u606f\u7c7b\u578b", "name": "message_type", "tip": "\u4fe1\u606f/\u8b66\u544a/\u9519\u8bef", "options": [{"label": "\u4fe1\u606f", "value": "message"}, {"label": "\u8b66\u544a", "value": "warning"}, {"label": "\u9519\u8bef", "value": "error"}], "default": "message", "dynamics": [{"key": "$this.message_type.show", "expression": "return $this.operate.value == ''open''"}], "required": true}, {"types": "NotifyPosition", "formType": {"type": "RADIO"}, "key": "position", "title": "\u6d88\u606f\u4f4d\u7f6e", "name": "position", "tip": "\u9876\u90e8/\u5e95\u90e8/\u53f3\u4e0b\u89d2", "options": [{"label": "\u9876\u90e8", "value": "top"}, {"label": "\u5e95\u90e8", "value": "bottom"}, {"label": "\u53f3\u4e0b\u89d2", "value": "bottom_right"}], "default": "top", "dynamics": [{"key": "$this.position.show", "expression": "return $this.operate.value == ''open''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "message_content", "title": "\u6d88\u606f\u5185\u5bb9", "name": "message_content", "tip": "\u63d0\u793a\u6846\u8981\u5c55\u793a\u7684\u5185\u5bb9\u4fe1\u606f\uff0c\u9650\u5236120\u4e2a\u5b57\u7b26", "default": "", "dynamics": [{"key": "$this.message_content.show", "expression": "return $this.operate.value == ''open''"}], "required": true, "limitLength": [-1, 120]}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "close_time", "title": "\u5173\u95ed\u8d85\u65f6\u65f6\u95f4\uff08\u79d2\uff09", "name": "close_time", "tip": "\u6d88\u606f\u901a\u77e5\u7684\u5c55\u793a\u65f6\u957f\uff0c\u9ed8\u8ba43\u79d2\uff0c0\u8868\u793a\u4e0d\u81ea\u52a8\u5173\u95ed", "default": 3, "value": [{"type": "str", "value": ""}], "level": "advanced", "dynamics": [{"key": "$this.close_time.show", "expression": "return $this.operate.value == ''open''"}], "required": false}], "outputList": [], "icon": "message-dialog", "helpManual": "\u6253\u5f00\u6216\u5173\u95ed\u6d88\u606f\u63d0\u793a\u6846\uff0c\u975e\u6a21\u6001\u5c55\u793a\uff0c\u4e0d\u963b\u585e\u6d41\u7a0b\u6267\u884c"}',NULL,'2026-08-16 10:34:02','2026-08-16 10:34:02');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('860','Dialog.data_table_box','{"key": "Dialog.data_table_box", "title": "\u6570\u636e\u8868\u683c\u5bf9\u8bdd\u6846", "version": "1.0.2", "src": "astronverse.dialog.dialog.Dialog().data_table_box", "comment": "", "inputList": [{"types": "Str", "formType": {"type": "INPUT"}, "key": "box_title", "title": "\u5bf9\u8bdd\u6846\u6807\u9898", "name": "box_title", "tip": "\u9650\u5236\u6807\u9898\u5185\u5bb9\u5b57\u7b26\u6570\u91cf\u4e3a50\u4e2a\u5b57\u7b26\uff0c\u4e0d\u8f93\u5165\u5219\u9ed8\u8ba4\u6807\u9898\u4e3a\"\u6570\u636e\u8868\u683c\u5bf9\u8bdd\u6846\"", "default": "\u6570\u636e\u8868\u683c\u5bf9\u8bdd\u6846", "required": false, "limitLength": [-1, 50]}, {"types": "Str", "formType": {"type": "INPUT"}, "key": "tip", "title": "\u63d0\u793a\u8bf4\u660e", "name": "tip", "tip": "\u4e3a\u6570\u636e\u8868\u683c\u7684\u4f7f\u7528\u65b9\u6cd5\u8fdb\u884c\u8bf4\u660e\uff0c\u8ba9\u4f7f\u7528\u8005\u66f4\u5bb9\u6613\u7406\u89e3\u5982\u4f55\u4f7f\u7528\u5f39\u51fa\u7684\u6570\u636e\u8868\u683c", "default": "", "required": false, "limitLength": [-1, 200]}, {"types": "List", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "default_data", "title": "\u521d\u59cb\u6570\u636e", "name": "default_data", "tip": "\u5f39\u51fa\u5bf9\u8bdd\u6846\u65f6\u8868\u683c\u5185\u9884\u7f6e\u7684\u6570\u636e\uff0c\u4e8c\u7ef4\u5217\u8868\uff0c\u53ef\u4e3a\u7a7a", "required": false}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "data_table", "title": "\u4fdd\u5b58\u8868\u683c\u6570\u636e\u81f3", "tip": "\u7528\u6237\u786e\u8ba4\u540e\u7684\u8868\u683c\u5185\u5bb9\uff0c\u4e8c\u7ef4\u5217\u8868"}, {"types": "Str", "formType": {"type": "RESULT"}, "key": "result_button", "title": "\u4fdd\u5b58\u70b9\u51fb\u7684\u6309\u94ae\u540d\u79f0\u81f3", "tip": ""}], "icon": "custom-dialog", "helpManual": "\u5f39\u51fa\u6570\u636e\u8868\u683c\u5bf9\u8bdd\u6846\uff0c\u53ef\u73b0