INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('861','TimeProcess.parse_datetime','{"key": "TimeProcess.parse_datetime", "title": "\u8f6c\u6362\u5230\u65e5\u671f\u65f6\u95f4", "version": "1.0.2", "src": "astronverse.dataprocess.time.TimeProcess().parse_datetime", "comment": "\u5c06\u6587\u672c @{text} \u6309\u89e3\u6790\u65b9\u5f0f @{parse_type} \u8f6c\u6362\u4e3a\u65e5\u671f\u65f6\u95f4\u5bf9\u8c61 @{parsed_time}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "text", "title": "\u6587\u672c", "name": "text", "tip": "\u8f93\u5165\u5f85\u8f6c\u6362\u7684\u65e5\u671f\u65f6\u95f4\u6587\u672c", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "ParseTimeType", "formType": {"type": "RADIO"}, "key": "parse_type", "title": "\u89e3\u6790\u65b9\u5f0f", "name": "parse_type", "tip": "\u81ea\u52a8\u8bc6\u522b\u5e38\u7528\u683c\u5f0f\uff0c\u6216\u4f7f\u7528\u81ea\u5b9a\u4e49\u683c\u5f0f\u4e32\u89e3\u6790", "options": [{"label": "\u81ea\u52a8\u8bc6\u522b", "value": "auto"}, {"label": "\u81ea\u5b9a\u4e49\u683c\u5f0f", "value": "custom"}], "default": "auto", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "custom_format", "title": "\u81ea\u5b9a\u4e49\u683c\u5f0f", "name": "custom_format", "tip": "Python\u683c\u5f0f\u4e32\uff0c\u5982 %Y-%m-%d %H:%M:%S", "default": "%Y-%m-%d", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.custom_format.show", "expression": "return $this.parse_type.value == ''custom''"}], "required": false}], "outputList": [{"types": "Date", "formType": {"type": "RESULT"}, "key": "parsed_time", "title": "\u65e5\u671f\u65f6\u95f4\u5bf9\u8c61", "tip": "\u8fd4\u56de\u8f6c\u6362\u540e\u7684\u65e5\u671f\u65f6\u95f4\u5bf9\u8c61"}], "icon": "output-formatted-time", "helpManual": "\u652f\u6301\u81ea\u52a8\u8bc6\u522b\u5e38\u7528\u683c\u5f0f\uff08\u59822024-01-01\u30012024/1/1\u30012024\u5e741\u67081\u65e5 00\u65f600\u520600\u79d2\uff09\uff0c\u6216\u4f7f\u7528\u81ea\u5b9a\u4e49\u683c\u5f0f\u4e32\uff08\u5982%Y-%m-%d %H:%M:%S\uff09\u89e3\u6790"}',NULL,'2026-08-16 10:55:54','2026-08-16 10:55:54');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('862','TimeProcess.get_datetime_info','{"key": "TimeProcess.get_datetime_info", "title": "\u83b7\u53d6\u65f6\u95f4\u8be6\u7ec6\u4fe1\u606f", "version": "1.0.2", "src": "astronverse.dataprocess.time.TimeProcess().get_datetime_info", "comment": "\u83b7\u53d6\u65f6\u95f4\u5bf9\u8c61 @{time} \u7684\u8be6\u7ec6\u4fe1\u606f\u5b57\u5178 @{datetime_info}", "inputList": [{"types": "Date", "formType": {"type": "INPUT_VARIABLE_PYTHON_DATETIME"}, "key": "time", "title": "\u65f6\u95f4\u5bf9\u8c61", "name": "time", "tip": "\u4e0d\u586b\u5219\u9ed8\u8ba4\u5f53\u524d\u7cfb\u7edf\u65f6\u95f4", "required": false}], "outputList": [{"types": "Dict", "formType": {"type": "RESULT"}, "key": "datetime_info", "title": "\u65f6\u95f4\u8be6\u7ec6\u4fe1\u606f", "tip": "\u8fd4\u56de\u5305\u542b\u5e74\u6708\u65e5\u65f6\u5206\u79d2\u3001\u661f\u671f\u3001\u5f53\u6708\u6700\u540e\u4e00\u5929\u3001\u5f53\u5e74\u7b2c\u51e0\u5468\u3001\u5f53\u5e74\u7b2c\u51e0\u5929\u7684\u5b57\u5178"}], "icon": "output-formatted-time", "helpManual": "\u8fd4\u56de\u5b57\u5178\uff0c\u5305\u542b\u5e74\u4efd/\u6708\u4efd/\u5929\u6570/\u5c0f\u65f6/\u5206\u949f/\u79d2\u6570/\u661f\u671f/\u5f53\u6708\u6700\u540e\u4e00\u5929/\u5f53\u5e74\u7b2c\u51e0\u5468/\u5f53\u5e74\u7b2c\u51e0\u5929"}',NULL,'2026-08-16 10:55:54','2026-08-16 10:55:54');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('863','System.get_selected_files','{"key": "System.get_selected_files", "title": "\u83b7\u53d6\u9009\u4e2d\u6587\u4ef6(\u5939)\u5217\u8868", "version": "1.0.1", "src": "astronverse.system.system.System().get_selected_files", "comment": "\u83b7\u53d6\u8d44\u6e90\u7ba1\u7406\u5668/\u684c\u9762(Finder)\u4e2d\u5f53\u524d\u9009\u4e2d\u7684\u6587\u4ef6(\u5939)\u5217\u8868\uff0c\u5e76\u4fdd\u5b58\u81f3\u53d8\u91cf @{selected_file_list}", "inputList": [], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "selected_file_list", "title": "\u9009\u4e2d\u6587\u4ef6(\u5939)\u5217\u8868", "tip": "\u8f93\u51fa\u9009\u4e2d\u9879\u7684\u7edd\u5bf9\u8def\u5f84\u5217\u8868\u5e76\u4fdd\u5b58\u81f3\u53d8\u91cf\uff0c\u6570\u636e\u7c7b\u578b\u4e3a\u5217\u8868"}], "icon": "get-file-list", "helpManual": "\u83b7\u53d6\u5f53\u524d\u8d44\u6e90\u7ba1\u7406\u5668\u7a97\u53e3\u6216\u684c\u9762\u4e2d\u9009\u4e2d\u7684\u6587\u4ef6\u548c\u6587\u4ef6\u5939\u8def\u5f84\u5217\u8868\uff0c\u9700\u5148\u624b\u52a8\u9009\u4e2d\u76ee\u6807\u9879\u540e\u518d\u6267\u884c\u8be5\u6307\u4ee4"}',NULL,'2026-08-16 11:54:54','2026-08-16 11:54:54');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('864','Folder.get_system_folder','{"key": "Folder.get_system_folder", "title": "\u83b7\u53d6\u7cfb\u7edf\u6587\u4ef6\u5939\u8def\u5f84", "version": "1.0.1", "src": "astronverse.system.folder.Folder().get_system_folder", "comment": "\u83b7\u53d6 @{system_folder_type} \u7cfb\u7edf\u6587\u4ef6\u5939\u8def\u5f84\uff0c\u5e76\u4fdd\u5b58\u81f3\u53d8\u91cf @{system_folder_path}", "inputList": [{"types": "SystemFolderType", "formType": {"type": "SELECT"}, "key": "system_folder_type", "title": "\u7cfb\u7edf\u6587\u4ef6\u5939\u540d\u79f0", "name": "system_folder_type", "tip": "\u901a\u8fc7\u4e0b\u62c9\u6846\u9009\u62e9\u76ee\u6807\u7cfb\u7edf\u6587\u4ef6\u5939\u540d\u79f0", "options": [{"label": "\u684c\u9762", "value": "desktop"}, {"label": "\u6587\u6863", "value": "documents"}, {"label": "\u4e0b\u8f7d", "value": "downloads"}, {"label": "\u56fe\u7247", "value": "pictures"}, {"label": "\u97f3\u4e50", "value": "music"}, {"label": "\u89c6\u9891", "value": "videos"}, {"label": "\u6536\u85cf\u5939", "value": "favorites"}, {"label": "\u5f00\u59cb\u83dc\u5355", "value": "start_menu"}, {"label": "\u4e34\u65f6\u76ee\u5f55", "value": "temp"}], "default": "desktop", "required": true}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "system_folder_path", "title": "\u7cfb\u7edf\u6587\u4ef6\u5939\u8def\u5f84", "tip": "\u4fdd\u5b58\u83b7\u53d6\u5230\u7684\u7cfb\u7edf\u6587\u4ef6\u5939\u8def\u5f84\u4e3a\u53d8\u91cf"}], "icon": "get-folder-list", "helpManual": "\u83b7\u53d6\u5f53\u524d\u8bbe\u5907\u7684\u7cfb\u7edf\u6587\u4ef6\u5939\u8def\u5f84\uff08\u684c\u9762/\u6587\u6863/\u4e0b\u8f7d/\u56fe\u7247/\u97f3\u4e50/\u89c6\u9891/\u6536\u85cf\u5939/\u5f00\u59cb\u83dc\u5355/\u4e34\u65f6\u76ee\u5f55\uff09\uff0c\u53ef\u63d0\u9ad8\u6d89\u53ca\u6587\u4ef6\u8def\u5f84\u6d41\u7a0b\u7684\u901a\u7528\u6027"}',NULL,'2026-08-16 11:54:54','2026-08-16 11:54:54');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('865','System.get_ime','{"key": "System.get_ime", "title": "\u83b7\u53d6\u8f93\u5165\u6cd5", "version": "1.0.1", "src": "astronverse.system.system.System().get_ime", "comment": "\u83b7\u53d6\u5f53\u524d\u6fc0\u6d3b\u7a97\u53e3\u7684\u8f93\u5165\u6cd5\u4e2d\u82f1\u6587\u8f93\u5165\u72b6\u6001\uff0c\u5e76\u4fdd\u5b58\u81f3\u53d8\u91cf @{ime_status}", "inputList": [], "outputList": [{"types": "String", "formType": {"type": "RESULT"}, "key": "ime_status", "title": "\u8f93\u5165\u6cd5\u72b6\u6001\u4fdd\u5b58\u81f3", "tip": "\u4fdd\u5b58\u83b7\u53d6\u5230\u7684\u8f93\u5165\u6cd5\u4e2d\u82f1\u6587\u72b6\u6001\u4e3a\u53d8\u91cf\uff0c\u8fd4\u56deunknow/english/chinese"}], "icon": "get-ime", "helpManual": "\u83b7\u53d6\u5f53\u524d\u6fc0\u6d3b\u7a97\u53e3\u8f93\u5165\u6cd5\u7684\u4e2d\u82f1\u6587\u8f93\u5165\u72b6\u6001\uff0c\u8fd4\u56de\u503c\u5305\u62ecunknow(\u672a\u77e5)\u3001english(\u82f1\u6587\u8f93\u5165\u72b6\u6001)\u3001chinese(\u4e2d\u6587\u8f93\u5165\u72b6\u6001)\uff0c\u4ec5\u652f\u6301Windows\u7cfb\u7edf"}',NULL,'2026-08-16 12:10:28','2026-08-16 12:10:28');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('866','System.set_ime','{"key": "System.set_ime", "title": "\u8bbe\u7f6e\u8f93\u5165\u6cd5", "version": "1.0.1", "src": "astronverse.system.system.System().set_ime", "comment": "\u8bbe\u7f6e\u5f53\u524d\u6fc0\u6d3b\u7a97\u53e3\u7684\u8f93\u5165\u6cd5\u4e3a @{ime_type}", "inputList": [{"types": "IMEStatusType", "formType": {"type": "RADIO"}, "key": "ime_type", "title": "\u5207\u6362\u5230", "name": "ime_type", "tip": "\u9009\u62e9\u5207\u6362\u5230\u82f1\u6587\u8f93\u5165\u6cd5\u6216\u4e2d\u6587\u8f93\u5165\u6cd5", "options": [{"label": "\u82f1\u6587\u8f93\u5165\u6cd5", "value": "english"}, {"label": "\u4e2d\u6587\u8f93\u5165\u6cd5", "value": "chinese"}], "default": "english", "required": true}], "outputList": [], "icon": "set-ime", "helpManual": "\u8bbe\u7f6e\u5f53\u524d\u6fc0\u6d3b\u7a97\u53e3\u7684\u8f93\u5165\u6cd5\u4e3a\u4e2d\u82f1\u6587\u8f93\u5165\u72b6\u6001\uff0c\u652f\u6301\u641c\u72d7\u62fc\u97f3/\u641c\u72d7\u4e94\u7b14/\u767e\u5ea6/QQ\u62fc\u97f3/QQ\u4e94\u7b14/Bing\u7b49\u4e3b\u6d41\u8f93\u5165\u6cd5\uff0c\u4ec5\u652f\u6301Windows\u7cfb\u7edf"}',NULL,'2026-08-16 12:10:28','2026-08-16 12:10:28');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('867','System.screensaver_start','{"key": "System.screensaver_start", "title": "\u5524\u8d77\u5c4f\u5e55\u4fdd\u62a4", "version": "1.0.1", "src": "astronverse.system.system.System().screensaver_start", "comment": "\u5524\u8d77\u5c4f\u5e55\u4fdd\u62a4\uff0c\u5982\u5df2\u8bbe\u7f6e\u5c4f\u4fdd\u63d0\u793a\u5219\u5168\u5c4f\u663e\u793a\u63d0\u793a\u6587\u5b57", "inputList": [], "outputList": [], "icon": "screensaver-start", "helpManual": "\u5524\u8d77\u5168\u5c4f\u7f6e\u9876\u7684\u5c4f\u5e55\u4fdd\u62a4\u7a97\u53e3\uff0c\u5982\u5df2\u901a\u8fc7\u3010\u8bbe\u7f6e\u5c4f\u4fdd\u63d0\u793a\u3011\u8bbe\u7f6e\u63d0\u793a\u6587\u5b57\u5219\u540c\u6b65\u663e\u793a\uff0c\u70b9\u51fb\u9f20\u6807\u6216\u6309\u4efb\u610f\u952e\u53ef\u9000\u51fa\u5c4f\u4fdd"}',NULL,'2026-08-16 12:10:28','2026-08-16 12:10:28');
