INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('889','Phone.connect','{"key": "Phone.connect", "title": "\u8fde\u63a5\u624b\u673a", "version": "1.0.0", "src": "astronverse.phone.phone.Phone().connect", "comment": "\u8fde\u63a5\u624b\u673a(@{serial})\uff0c\u8fde\u63a5\u5bf9\u8c61\u4fdd\u5b58\u81f3(@{conn})", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "target_type", "title": "\u8fde\u63a5\u5bf9\u8c61", "name": "target_type", "tip": "\u6307\u5b9a\u624b\u673a/\u8fd0\u884c\u65f6\u81ea\u52a8\u9009\u62e9/\u6240\u6709\u5df2\u8fde\u63a5\u7684\u624b\u673a", "default": "auto", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "serial", "title": "\u624b\u673aserial", "name": "serial", "tip": "\u6307\u5b9a\u624b\u673a\u65f6\u586b\u5199, \u53ef\u901a\u8fc7\u3010\u83b7\u53d6\u624b\u673a\u8bbe\u5907\u5217\u8868\u3011\u67e5\u770b", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.serial.show", "expression": "return $this.target_type.value == ''specified''"}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "ignore_failed", "title": "\u5ffd\u7565\u8fde\u63a5\u5931\u8d25\u7684\u624b\u673a", "name": "ignore_failed", "tip": "\u8fde\u63a5\u6240\u6709\u624b\u673a\u65f6\u751f\u6548, \u52fe\u9009\u5219\u8df3\u8fc7\u8fde\u63a5\u5931\u8d25\u7684\u624b\u673a", "options": [{"label": "\u662f", "value": true}, {"label": "\u5426", "value": false}], "default": true, "dynamics": [{"key": "$this.ignore_failed.show", "expression": "return $this.target_type.value == ''all''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "custom_name", "title": "\u81ea\u5b9a\u4e49\u624b\u673a\u540d\u79f0", "name": "custom_name", "tip": "\u81ea\u5b9a\u4e49\u624b\u673a\u8fde\u63a5\u540d\u79f0, \u4fdd\u5b58\u5728\u8fde\u6